window.ABDOMINAL_DATA = {"course": {"title": "Semiologia Abdominal · Turbo TEMI 360X", "description": "Aprenda a examinar com técnica, interpretar com fisiopatologia e reconhecer o abdome que exige intervenção urgente. Aulas curtas, prática de evocação, casos fictícios e tutores educativos para aprimorar o exame físico.", "scope": "Formação médica em semiologia abdominal de adultos, com foco em abdome agudo potencialmente cirúrgico e aplicação em emergência, enfermaria e UTI. As técnicas devem ser praticadas com consentimento, supervisão e respeito ao conforto. Crianças e gestantes exigem adaptação própria. Os exercícios são educacionais; não produzem diagnóstico, prescrição ou classificação automática de pacientes.", "bookNote": "Porto & Porto, Semiologia Médica, 9ª edição, Guanabara Koogan, 2025, e López & Laurentys-Medeiros, Semiologia Médica: as bases do diagnóstico clínico, Atheneu, são referências bibliográficas orientadoras solicitadas pelo usuário. A edição de López disponível ao usuário não foi informada; sua existência e autoria foram verificadas em catálogo universitário. Os livros integrais não foram fornecidos nem consultados nesta elaboração. O texto é original, apoiado nas fontes abertas indicadas, sem reproduzir capítulos, figuras, páginas ou atribuir aos livros recomendações não verificadas.", "lessons": [{"id": "a01", "title": "Antes da mão: segurança, consentimento e preparo", "lead": "O primeiro resultado do exame é decidir se há tempo para um exame completo.", "blocks": [{"title": "Observe a pessoa antes do abdome", "text": "Avalie consciência, fala, respiração, perfusão, pressão arterial, frequência cardíaca, temperatura e intensidade da dor. Confusão, síncope, extremidades frias, hipotensão, sangramento importante ou deterioração rápida exigem atendimento imediato. Ressuscitação, analgesia e acionamento das equipes adequadas caminham junto da investigação; uma sequência extensa de manobras não pode atrasar essas ações."}, {"title": "Prepare um encontro clínico", "text": "Apresente-se, confirme a identificação no atendimento real, explique o objetivo e peça consentimento. Pergunte onde dói mais e combine que o exame será interrompido se necessário. Higienize as mãos, aqueça-as e garanta privacidade. Exponha o abdome de modo suficiente, preservando tórax e genitais; examine virilhas ou regiões íntimas apenas com indicação, explicação e medidas apropriadas de acompanhamento."}, {"title": "Posicione para relaxar", "text": "No exame de rotina, use decúbito dorsal, cabeça apoiada, braços ao lado do corpo e discreto apoio sob os joelhos quando confortável. Braços atrás da cabeça tensionam a parede. O examinador costuma ficar à direita, mas adapta sua posição ao objetivo. Não force o paciente dispneico, com limitação ortopédica ou dor intensa a assumir uma postura padronizada."}, {"title": "Treine sem causar sofrimento", "text": "Comece pela inspeção e pelas áreas menos dolorosas. Ofereça analgesia apropriada sem esperar fechar o diagnóstico; registre seu momento e reavalie. A qualidade do exame depende da resposta observada, e não da força aplicada. Em simulação, treine posicionamento e comunicação; em pacientes, evite repetições de descompressão dolorosa por vários examinadores apenas para demonstrar um sinal."}], "recall": {"question": "O que fazer se o paciente piorar antes de terminar a sequência?", "answer": "Interromper o exame prolongado, reconhecer a instabilidade, iniciar suporte e acionar ajuda. Completar manobras não tem prioridade sobre ressuscitação e avaliação urgente."}, "sources": ["abd-curso-exame", "abd-curso-analgesia", "abd-curso-nice-aorta"]}, {"id": "a02", "title": "A história da dor constrói o primeiro mapa", "lead": "Localização, tempo e evolução valem mais quando são interpretados juntos.", "blocks": [{"title": "Reconstrua a sequência", "text": "Peça que a pessoa mostre com a mão onde a dor começou e onde está agora. Determine início súbito ou gradual, duração, progressão, episódios prévios, intensidade, caráter, irradiação, migração e fatores de melhora ou piora. Dor que atinge intensidade máxima desde o início aumenta a preocupação com eventos vasculares, perfuração e outras emergências, mas não identifica uma causa isoladamente."}, {"title": "Separe mecanismos", "text": "Dor visceral costuma ser mal delimitada e pode acompanhar distensão ou contração de vísceras; o paciente frequentemente aponta uma região com a palma. Irritação do peritônio parietal favorece dor localizada e agravada pelo movimento. Dor referida é percebida à distância por convergência de aferências nervosas. São modelos de raciocínio: apresentações reais podem misturar mecanismos ou fugir do padrão clássico."}, {"title": "Pergunte o que acompanha", "text": "Investigue náuseas, vômitos e sua relação temporal com a dor, eliminação de gases e fezes, diarreia, sangramento, febre, anorexia, icterícia, colúria, acolia, disúria e hematúria. Inclua possibilidade de gestação e sintomas genitais quando pertinentes. Evacuar ou ter diarreia não afasta obstrução parcial nem apendicite; a ordem dos sintomas modifica probabilidades, sem funcionar como regra absoluta."}, {"title": "Procure o contexto que muda o risco", "text": "Pergunte sobre cirurgias anteriores, hérnias, fibrilação atrial, doença vascular, anticoagulantes, anti-inflamatórios, imunossupressão, álcool e procedimentos recentes. Registre o último estado funcional conhecido e os tratamentos já recebidos. Transforme a narrativa em uma frase: início + topografia + evolução + associados + risco. Essa representação orienta o exame direcionado e impede que um epônimo isolado domine a avaliação."}], "recall": {"question": "Migração de dor periumbilical para a fossa ilíaca direita confirma apendicite?", "answer": "Não. É um padrão compatível com evolução de dor visceral para irritação parietal, que aumenta a suspeita e deve ser integrado ao exame, risco clínico e imagem quando indicada."}, "sources": ["abd-curso-gi", "abd-curso-apendicite", "abd-curso-nice-gestacao"]}, {"id": "a03", "title": "Quatro quadrantes, nove regiões e camadas", "lead": "O mapa anatômico organiza hipóteses; não mantém cada órgão dentro de uma caixa.", "blocks": [{"title": "Quatro quadrantes", "text": "Uma linha mediana e outra transversal pelo umbigo dividem o abdome em quadrantes superior direito, superior esquerdo, inferior direito e inferior esquerdo. Direita e esquerda são sempre as do paciente. Esse mapa facilita comunicação rápida, principalmente quando há dor ou massa. Use palavras por extenso no primeiro registro para evitar ambiguidades de siglas entre equipes."}, {"title": "Nove regiões", "text": "Duas linhas medioclaviculares e os planos subcostal e intertubercular definem, de cima para baixo: hipocôndrio direito, epigástrio e hipocôndrio esquerdo; flanco direito, região umbilical e flanco esquerdo; fossa ilíaca direita, hipogástrio e fossa ilíaca esquerda. São referências de superfície, influenciadas por biotipo, respiração, distensão, gestação e crescimento de órgãos ou massas."}, {"title": "Pense além da superfície", "text": "Em cada região, considere pele, músculo, peritônio, vísceras, retroperitônio e estruturas extra-abdominais. Dor epigástrica pode vir de estômago, pâncreas, aorta ou coração; dor superior pode refletir doença torácica. A posição do apêndice varia. Bexiga distendida ocupa o hipogástrio e pode ascender; baço muito aumentado pode ultrapassar a linha mediana."}, {"title": "Descreva para outro examinador encontrar", "text": "Informe ponto de máxima dor, extensão, profundidade que a provoca, presença de defesa e irradiação. Para massas, acrescente dimensões estimadas, consistência, mobilidade, relação com respiração e parede. Na simulação, aponte as regiões no próprio corpo sem provocar dor e explique dois diagnósticos de mecanismos diferentes para cada área. O objetivo é localizar e abrir hipóteses antes de estreitá-las."}], "recall": {"question": "Qual é o erro de chamar toda dor no hipocôndrio direito de biliar?", "answer": "Confundir topografia com etiologia. Fígado, duodeno, cólon, rim direito, parede, pleura e pulmão também podem gerar dor nessa região."}, "sources": ["abd-curso-exame", "abd-curso-gi", "abd-curso-inspecao"]}, {"id": "a04", "title": "Inspeção: leia a parede e o comportamento", "lead": "Uma observação cuidadosa pode poupar manobras desnecessárias.", "blocks": [{"title": "Observe sem tocar", "text": "Examine o contorno de frente e tangencialmente: plano, globoso, escavado, distensão difusa ou assimétrica, abaulamentos e retrações. Registre cicatrizes, drenos, estomas, hérnias aparentes, lesões cutâneas, equimoses e circulação colateral. Uma cicatriz não conta toda a história cirúrgica; confirme procedimento, data e complicações. Em estomas, observe cor, perfusão e pele adjacente."}, {"title": "Movimento e postura", "text": "Acompanhe alguns ciclos respiratórios e mudanças espontâneas de posição. O paciente com irritação peritoneal pode evitar movimento; quem tem cólica pode mostrar inquietação. Esses comportamentos não são testes diagnósticos. Respiração superficial, contração da parede e medo também alteram a observação. Não peça saltos ou movimentos dolorosos a alguém instável ou com suspeita evidente de peritonite."}, {"title": "Interprete alterações visíveis", "text": "Distensão pode decorrer de gás, líquido, gordura, gestação, retenção urinária, organomegalia ou massa. Equimoses periumbilicais ou em flancos, tradicionalmente relacionadas a Cullen e Grey Turner, sugerem possível sangramento profundo em contexto adequado, mas são inespecíficas e podem ser tardias. Não são sinônimos de pancreatite. Ondas peristálticas visíveis levantam hipóteses, sem localizar sozinhas uma obstrução."}, {"title": "Conecte com o exame geral", "text": "Procure icterícia, palidez, sinais de desidratação, edema e repercussão respiratória. Circulação venosa aparente merece descrição, mas uma fotografia isolada não determina o sentido do fluxo nem confirma hipertensão portal. Na prática de estudo, descreva primeiro o que realmente vê e só depois a interpretação: 'equimose em flanco' é dado; 'possível sangramento retroperitoneal' é hipótese que exige avaliação."}], "recall": {"question": "Equimose de flanco permite afirmar pancreatite hemorrágica?", "answer": "Não. É um achado de alerta inespecífico. Sangramento retroperitoneal e outras causas precisam ser considerados conforme a história, a estabilidade e a investigação."}, "sources": ["abd-curso-inspecao", "abd-curso-ascite-stanford", "abd-curso-atlanta"]}, {"id": "a05", "title": "Ausculta: escute, descreva e respeite os limites", "lead": "Ruídos intestinais acrescentam contexto; não decidem sozinhos se há obstrução ou isquemia.", "blocks": [{"title": "Como executar", "text": "Em ambiente silencioso, aqueça o diafragma do estetoscópio e encoste-o suavemente na pele. Escute em pontos distribuídos pelo abdome, sem conversar durante a observação. A sequência didática habitual é inspeção, ausculta, percussão e palpação. Ela ajuda a padronizar o aprendizado; não deve atrasar o atendimento de um paciente grave nem exigir reinício de todo o exame após um toque."}, {"title": "O que registrar", "text": "Descreva presença, padrão intermitente, intensidade e qualidade dos sons. Evite inventar um número exato de eventos por minuto quando não houve contagem. Sons se propagam pelo abdome e não correspondem necessariamente à alça sob o estetoscópio. Se nada foi ouvido inicialmente, prolongue a ausculta conforme o contexto e registre a duração; alguns segundos de silêncio não comprovam ausência de atividade intestinal."}, {"title": "Concilie tradição e evidência", "text": "Há convenção de auscultar antes de mobilizar a parede, mas pequenos estudos não mostraram alteração relevante da frequência dos sons após palpação ou percussão em populações selecionadas. Isso não valida qualquer sequência em todo abdome agudo. O ponto útil é manter técnica consistente e não tratar uma regra tradicional como marcador absoluto de qualidade ou de segurança diagnóstica."}, {"title": "Sons que pedem integração", "text": "Ruídos agudos em salvas podem acompanhar obstrução; redução pode ocorrer em íleo, peritonite, pós-operatório e sob medicamentos. Há sobreposição e variabilidade entre observadores. Sopros vasculares indicam turbulência e justificam correlação com pulsos, fatores de risco e imagem. Sua ausência não afasta aneurisma ou doença vascular. Atritos sobre fígado ou baço são raros e exigem contextualização, sem pressão excessiva do aparelho."}], "recall": {"question": "O abdome está silencioso por 15 segundos. O diagnóstico é íleo?", "answer": "Não. A amostra é curta e a ausculta isolada tem limitações. É preciso observar por mais tempo quando apropriado e integrar distensão, dor, vômitos, trânsito, medicamentos e imagem."}, "sources": ["abd-curso-exame", "abd-curso-sons-estudo", "abd-curso-bologna"]}, {"id": "a06", "title": "Percussão: gás, líquido e limites de órgãos", "lead": "Compare a mudança do som, sem transformar a mão em um instrumento de medida exata.", "blocks": [{"title": "Prepare a técnica", "text": "Apoie firmemente a falange distal de um dedo da mão não dominante na parede, mantendo os outros dedos afastados da pele. Percuta com movimento curto do dedo médio da outra mão, vindo principalmente do punho. Use força leve e comparável entre áreas. Em região muito dolorosa, a percussão deve ser delicada ou dispensada; não é necessário produzir um som alto."}, {"title": "Reconheça os sons", "text": "Timpanismo é um som mais ressonante associado a gás; macicez é mais abafada e pode corresponder a órgão sólido, líquido ou massa. A distribuição habitual contém predomínio de timpanismo nas alças e macicez em áreas de órgãos sólidos. Gordura, tensão muscular, conteúdo intestinal e posicionamento alteram a transmissão. Uma transição duvidosa deve ser registrada como limitação, e não convertida em achado positivo."}, {"title": "Siga um percurso", "text": "Compare quadrantes, delimite áreas de macicez e, quando pertinente, estime a extensão hepática na linha medioclavicular. Em distensão, procure diferença entre centro e flancos e depois mudança com o decúbito. Macicez suprapúbica pode acompanhar bexiga distendida, mas exige correlação clínica ou ultrassom. Não use medidas de percussão como substitutas automáticas das dimensões de órgãos obtidas por imagem."}, {"title": "O significado de Jobert", "text": "O desaparecimento da macicez hepática, tradicionalmente chamado sinal de Jobert, pode ocorrer com interposição de gás entre fígado e parede em pneumoperitônio. Também existem explicações alternativas, como alça interposta ou distensão. A ausência desse sinal não exclui perfuração; sua presença não informa qual víscera rompeu. Dor súbita e sinais peritoneais sustentam a urgência mesmo com percussão inconclusiva."}], "recall": {"question": "Timpanismo sobre a área hepática fecha o diagnóstico de perfuração?", "answer": "Não. É uma pista possível de gás interposto e deve ser confrontada com quadro clínico e imagem. Perfuração pode ocorrer sem esse achado."}, "sources": ["abd-curso-inspecao", "abd-curso-figado", "abd-curso-perfuracao"]}, {"id": "a07", "title": "Palpação superficial: dor, defesa e parede", "lead": "Comece longe da dor e observe a resposta, sem forçar relaxamento.", "blocks": [{"title": "Faça contato gradual", "text": "Avise que vai tocar, pergunte novamente o local mais doloroso e comece em região distante. Use a superfície palmar dos dedos, mão relaxada e pressão suave. Percorra o abdome sistematicamente, mantendo contato amplo em vez de picotar a pele. Observe o rosto, a respiração, a tensão muscular e a fala; o paciente pode comunicar desconforto antes de responder verbalmente."}, {"title": "O que você procura", "text": "Identifique dor à palpação, resistência da parede, alterações superficiais, hérnias aparentes e hipersensibilidade. Descreva a intensidade de pressão necessária para provocar o sintoma e a topografia. Dor referida pelo paciente e dor provocada pelo exame são informações complementares, não concorrentes. Respeite diferenças de expressão relacionadas a idade, cultura, neurodivergência, sedação ou comprometimento cognitivo."}, {"title": "Defesa voluntária e involuntária", "text": "A contração por medo, frio ou antecipação pode diminuir com explicação, apoio dos joelhos e expiração tranquila. Resistência persistente, involuntária e compatível com o contexto inflamatório aumenta a preocupação com irritação peritoneal. Os termos defesa e rigidez variam entre escolas; no registro, descreva se a resistência é localizada ou difusa e se cede ao relaxamento, em vez de depender apenas do nome."}, {"title": "Saiba quando parar", "text": "Se a dor é intensa e há evidência suficiente de peritonismo, evite uma série repetida de estímulos para 'comprovar'. Em idoso, imunossuprimido ou sedado, parede pouco reativa não afasta doença grave. O próximo passo pode ser suporte e avaliação cirúrgica com investigação direcionada. Treinar a percepção de força adequada em simulador e receber feedback do preceptor é mais útil que colecionar sinais dolorosos."}], "recall": {"question": "Qual registro comunica melhor o achado: 'abdome ruim' ou uma descrição objetiva?", "answer": "Descreva o local da dor, a pressão que a provoca, resistência localizada ou difusa, resposta ao relaxamento e limitações. Isso permite comparação na reavaliação."}, "sources": ["abd-curso-exame", "abd-curso-inspecao", "abd-curso-imunocomprometido"]}, {"id": "a08", "title": "Palpação profunda: órgãos e massas", "lead": "Aprofunde a informação apenas até o limite de conforto e segurança.", "blocks": [{"title": "Avance com método", "text": "Depois da palpação superficial, aumente gradualmente a pressão nas regiões em que isso é apropriado. Sincronizar o contato com a expiração pode facilitar o relaxamento. Na técnica bimanual sobreposta, a mão superior auxilia a pressão e a inferior percebe os achados. Não há profundidade fixa que sirva para todos os biotipos; a parede e o objetivo determinam a execução."}, {"title": "Caracterize o que foi encontrado", "text": "Para uma massa, registre região, dimensões aproximadas, contorno, consistência, superfície, mobilidade, dor e relação com respiração. Descreva pulsação sem fazer compressões repetidas sobre uma massa suspeita de aneurisma. Fezes, músculo contraído, borda hepática e outras estruturas podem ser confundidos com massa. Na dúvida, explicite a incerteza e recorra ao método confirmatório apropriado."}, {"title": "Parede ou cavidade?", "text": "Uma alteração superficial pode permanecer evidente quando a musculatura é contraída, enquanto estruturas profundas podem ficar menos acessíveis. O raciocínio de Carnett compara a dor focal com a parede relaxada e contraída; é mais útil no contexto de dor da parede do que para excluir doença visceral aguda. Não peça contração vigorosa se isso intensifica sofrimento ou se o paciente não pode colaborar."}, {"title": "Limites que previnem erros", "text": "Palpação profunda não é uma tentativa de sentir diretamente todos os órgãos. O pâncreas normal não costuma ser palpável; ausência de massa não descarta doença retroperitoneal. Obesidade, ascite, gás, curativos e dor reduzem o rendimento. Termine explicando o que o exame permitiu e o que permaneceu indeterminado. Registre achados positivos e negativos relevantes, sem preencher uma lista automática de normalidade."}], "recall": {"question": "Uma massa pulsátil dolorosa deve ser comprimida repetidamente para medir seu tamanho?", "answer": "Não. O quadro pede avaliação vascular urgente e imagem adequada ao estado clínico. A palpação não fornece a medida segura necessária para a decisão."}, "sources": ["abd-curso-gi", "abd-curso-exame", "abd-curso-nice-aorta"]}, {"id": "a09", "title": "Fígado e vias biliares: da borda ao Murphy", "lead": "Diferencie hepatomegalia, dor subcostal e interrupção inspiratória.", "blocks": [{"title": "Palpe a borda hepática", "text": "Localize o rebordo costal direito e estime pela percussão onde começar. Posicione a mão abaixo da área esperada da borda, avance em pequenos passos e peça uma inspiração confortável. Sinta a descida do fígado contra os dedos, sem escavar sob as costelas. Caracterize dor, consistência e regularidade. Uma borda palpável não significa automaticamente aumento de volume: posição diafragmática e biotipo interferem."}, {"title": "Execute Murphy com delicadeza", "text": "Em paciente estável e capaz de cooperar, faça pressão gradual na região subcostal direita, usando a linha medioclavicular como referência de superfície para a projeção vesicular, e peça inspiração. O achado clássico é interrupção súbita da inspiração por dor naquele local, não apenas sensibilidade genérica no hipocôndrio. Interrompa após resposta clara. O Murphy ultrassonográfico é provocado pelo transdutor sobre a vesícula identificada na imagem; é um procedimento diferente do sinal clínico."}, {"title": "Integre a síndrome biliar", "text": "Dor persistente no hipocôndrio direito, inflamação sistêmica e achados de imagem orientam colecistite. Nenhum achado isolado confirma ou exclui a doença. Murphy pode estar ausente em grupos de maior risco ou apresentações complicadas. Icterícia, febre e dor biliar levantam preocupação com colangite; hipotensão ou confusão agravam a urgência. Ausência da tríade completa não torna seguro descartar infecção biliar."}, {"title": "Use Courvoisier como pista", "text": "Icterícia com vesícula aumentada e indolor é a combinação tradicional associada ao sinal de Courvoisier e sugere investigação de obstrução biliar distal, inclusive neoplasia. É uma associação clínica com exceções; não demonstra câncer nem exclui cálculo. O exame deve orientar ultrassonografia e avaliação complementar, com atenção a perda ponderal, prurido, colúria e características da evolução."}], "recall": {"question": "Qual é a diferença entre Murphy positivo e dor inespecífica no hipocôndrio direito?", "answer": "Murphy clínico clássico requer interrupção inspiratória por dor durante a palpação subcostal direita. Sensibilidade local isolada não equivale ao sinal, e ambos precisam de contexto e investigação."}, "sources": ["abd-curso-figado", "abd-curso-colecistite", "abd-curso-vias-infecciosas"]}, {"id": "a10", "title": "Baço: palpação, percussão e segurança", "lead": "Um baço palpável merece investigação; um baço não palpável ainda pode estar aumentado.", "blocks": [{"title": "Entenda sua posição", "text": "O baço ocupa o hipocôndrio esquerdo, junto ao diafragma, protegido pelas costelas. Quando aumenta, pode se estender em direção inferior e medial, por vezes muito além da borda costal. Por isso, começar a busca apenas junto às costelas pode deixar passar uma grande esplenomegalia. A anatomia orienta a trajetória da mão, mas não permite estimar volume com precisão."}, {"title": "Como palpar", "text": "Com o paciente confortável, comece em região inferior e avance gradualmente em direção ao hipocôndrio esquerdo, procurando a borda que desce com a inspiração. A outra mão pode apoiar suavemente a região costal posterior esquerda. Se não houver dor aguda nem contraindicação à mudança de posição, o decúbito lateral direito pode facilitar. Evite insistência vigorosa sobre um órgão doloroso ou potencialmente frágil."}, {"title": "Como interpretar", "text": "A borda com incisura, a direção de crescimento e a mobilidade respiratória ajudam a reconhecer o baço, mas esses elementos podem ser pouco evidentes. Percussão do espaço de Traube ou técnicas como Castell acrescentam pistas, sujeitas a gás, conteúdo gástrico, obesidade e derrame pleural. Não confirmar aumento pelo exame físico não equivale a excluí-lo; o ultrassom esclarece dúvidas de tamanho e natureza."}, {"title": "Do achado à hipótese", "text": "Considere hipertensão portal, doenças hematológicas, infecções e outras causas conforme história e hemograma. Dor súbita no hipocôndrio esquerdo, dor referida ao ombro, síncope, trauma ou instabilidade mudam a prioridade para possível sangramento ou lesão esplênica. Nesse cenário, não se deve persistir em palpação para demonstrar borda ou incisura. O valor do exame está também em reconhecer quando a próxima informação deve vir da imagem e da equipe cirúrgica."}], "recall": {"question": "Por que começar longe do rebordo costal ao procurar o baço?", "answer": "Porque uma esplenomegalia importante pode ocupar regiões inferiores e mediais. Começar muito alto pode fazer a mão ficar acima da borda inferior do órgão."}, "sources": ["abd-curso-baco", "abd-curso-stanford-organos", "abd-curso-trauma"]}, {"id": "a11", "title": "Rins, região lombar e bexiga", "lead": "Dor lombar provocada localiza uma região; não identifica sozinha infecção ou cálculo.", "blocks": [{"title": "Construa a hipótese urinária", "text": "Pergunte sobre disúria, urgência, frequência, hematúria, febre, náuseas, redução do volume urinário e irradiação da dor para a virilha. Distinga dor em cólica, que pode acompanhar obstrução, de dor contínua, sem tratar essa diferença como prova. Cólica ureteral pode ter hematuria ausente; uma urina alterada também não exclui outra causa abdominal concomitante."}, {"title": "Exame renal", "text": "A palpação bimanual coloca uma mão na região lombar para apoio e outra anteriormente, abaixo do rebordo costal, com pressão progressiva durante a respiração. O polo inferior direito pode ser perceptível em pessoas magras. Há variantes clássicas de posição, descritas no catálogo de técnicas. A palpação não é obrigatória quando dor intensa ou situação clínica torna o ganho informativo pequeno."}, {"title": "Giordano não é um golpe forte", "text": "Procure sensibilidade na região do ângulo costovertebral, junto à 12ª costela e à coluna. Quando indicado, a punho-percussão deve ser leve, preferencialmente sobre a mão de apoio, comparando lados e interrompendo à dor. Não golpeie com força e não repita uma resposta já clara. O achado pode ocorrer em pielonefrite, obstrução e causas musculoesqueléticas; resultado negativo não exclui doença renal ou retroperitoneal."}, {"title": "Reconheça a urgência", "text": "Dor no flanco com febre ou sepse e evidência de obstrução exige avaliação urológica urgente para descompressão, além do tratamento da infecção. Anúria, rim único funcional e piora renal tornam o cenário mais preocupante. No hipogástrio, abaulamento, macicez e desconforto podem sugerir retenção urinária; ultrassom vesical ajuda a confirmar. Não atribua toda massa suprapúbica a bexiga sem considerar outras hipóteses."}], "recall": {"question": "Febre, dor no flanco e hidronefrose podem ser tratados como cólica simples?", "answer": "Não. Infecção em sistema obstruído é emergência urológica e pode exigir drenagem urgente. Analgesia isolada não resolve a fonte."}, "sources": ["abd-curso-exame", "abd-curso-eau", "abd-curso-uro-emergencias"]}, {"id": "a12", "title": "Ascite e macicez móvel", "lead": "Demonstre que o líquido muda de lugar; depois investigue por que ele está ali.", "blocks": [{"title": "Reconheça a distribuição", "text": "Ascite é líquido livre na cavidade peritoneal. Em decúbito dorsal, volumes suficientes podem produzir abaulamento dos flancos e timpanismo central, pois alças com gás tendem a ocupar posição mais anterior. Nem toda distensão é ascite; adiposidade, gás, gestação, massas e retenção urinária entram no diagnóstico diferencial. Pequenos volumes frequentemente escapam ao exame físico."}, {"title": "Macicez móvel em quatro ações", "text": "Percuta do centro timpânico em direção ao flanco e localize a transição para macicez. Mantenha a referência. Se examinar o flanco direito, ajude o paciente a virar para o lado esquerdo, deixando a área testada acima, e aguarde redistribuição do líquido. Percuta novamente a mesma área: a passagem de macicez a timpanismo apoia líquido móvel. Faça a mudança apenas se confortável e segura; registre o lado e a alteração observada."}, {"title": "Onda líquida e suas limitações", "text": "Na pesquisa de onda, uma mão recebe a transmissão no flanco enquanto a outra produz um toque no lado oposto; a borda da mão do paciente ou de um auxiliar na linha mediana reduz a transmissão pela parede. Gordura e tecido subcutâneo podem gerar falsos positivos. Nenhuma dessas manobras determina a composição do líquido, sua causa ou se há infecção."}, {"title": "Complete com diagnóstico etiológico", "text": "Integre estigmas hepáticos, pressão venosa jugular, edema e história. Ultrassom identifica líquido e auxilia procedimentos. Ascite nova clinicamente relevante pede investigação; em cirrose com internação aguda, a paracentese diagnóstica é essencial mesmo sem febre ou dor. Neutrófilos ≥250 células/mm³ no líquido sustentam peritonite bacteriana espontânea quando não há fonte intra-abdominal cirurgicamente tratável. Achados focais, deterioração ou evolução incompatível exigem também investigar peritonite secundária; cultura negativa não exclui infecção."}], "recall": {"question": "Macicez móvel positiva diferencia ascite infectada de não infectada?", "answer": "Não. Ela sugere líquido móvel. Infecção depende da avaliação clínica e análise do líquido, incluindo contagem de neutrófilos e cultura, conforme indicação."}, "sources": ["abd-curso-ascite-stanford", "abd-curso-aasld", "abd-curso-easl"]}, {"id": "a13", "title": "Peritônio e apêndice: interpretar sem torturar", "lead": "A irritação peritoneal importa mais que a quantidade de epônimos positivos.", "blocks": [{"title": "Reconheça o mecanismo", "text": "A inflamação do peritônio parietal favorece dor bem localizada, piora com movimento e resistência involuntária da parede. Tosse espontânea, mudança de posição e percussão delicada podem fornecer informação sem necessidade de repetida descompressão brusca. Peritonismo pode ser localizado ou difuso. Sua causa pode ser inflamatória, perfurativa, hemorrágica ou isquêmica; não é equivalente a apendicite."}, {"title": "Se a descompressão for necessária", "text": "Explique o que fará, aplique pressão progressiva e observe se a retirada da pressão provoca dor mais intensa. O sinal de Blumberg descreve dor à descompressão; em muitas escolas é associado à fossa ilíaca direita, mas a irritação peritoneal não fica restrita a essa região. Não é preciso surpreender o paciente nem retirar a mão de modo teatral. Pare depois de uma resposta informativa."}, {"title": "Localize o apêndice provável", "text": "Migração da dor para a fossa ilíaca direita e sensibilidade nessa área apoiam a hipótese. Rovsing provoca dor à direita ao comprimir a região esquerda; psoas e obturador relacionam-se ao contato inflamatório com estruturas musculares e variam conforme a posição apendicular. Um apêndice retrocecal ou pélvico pode produzir sinais diferentes. Não ter todos os sinais clássicos é comum e não autoriza exclusão."}, {"title": "Vá além do epônimo", "text": "Escore clínico validado, laboratório e imagem devem ser combinados conforme risco e população; os sinais não substituem essa integração. Em gravidez, idosos e imunossuprimidos, apresentação e decisões de imagem precisam de adaptação. Peritonismo difuso ou instabilidade pede avaliação urgente, sem esperar que uma bateria completa de manobras fique positiva. Uma boa conclusão separa hipótese, gravidade e próxima ação necessária."}], "recall": {"question": "Três sinais apendiculares negativos afastam apendicite?", "answer": "Não. A sensibilidade é limitada e depende da posição do apêndice, tempo de doença e paciente. A decisão combina evolução, risco, exame global e investigação."}, "sources": ["abd-curso-apendicite", "abd-curso-inspecao", "abd-curso-imunocomprometido"]}, {"id": "a14", "title": "Parede abdominal, hérnias e exames direcionados", "lead": "Não esqueça causas externas à cavidade nem transforme exame íntimo em rotina automática.", "blocks": [{"title": "Inspecione os pontos vulneráveis", "text": "Examine umbigo, linha média, cicatrizes e regiões inguinais quando houver indicação. Em pessoa estável e confortável, ficar em pé, tossir ou aumentar suavemente a pressão abdominal pode evidenciar um abaulamento. Identifique dor, relação com a postura e alterações de pele. Explique qualquer exposição adicional e ofereça acompanhamento apropriado. Uma hérnia pequena ou profunda pode não ser visível."}, {"title": "Encarceramento e estrangulamento", "text": "Hérnia não redutível é um achado diferente de hérnia com comprometimento vascular. Dor importante, piora contínua, vômitos, distensão, pele alterada ou sinais sistêmicos elevam a suspeita de complicação e pedem avaliação cirúrgica. Não force redução de uma hérnia dolorosa com suspeita de estrangulamento. A ausência de grande distensão não exclui uma alça comprometida, especialmente em apresentações parciais."}, {"title": "Dor da parede", "text": "Um ponto pequeno, bem localizado e reproduzível, que persiste ou piora ao contrair a parede, pode favorecer origem parietal no teste de Carnett. Considere aprisionamento nervoso, lesão muscular, hérnia e hematoma, inclusive sob anticoagulação. O resultado não é garantia de benignidade e não exclui processo visceral concomitante. Em dor aguda importante, o contexto pesa mais que uma resposta isolada."}, {"title": "Quando ampliar o exame", "text": "Avaliação genital, pélvica ou retal deve responder a uma hipótese ou necessidade concreta, com consentimento, privacidade e técnica apropriada. Dor testicular pode se manifestar inicialmente como dor abdominal, e torção exige urgência. Toque retal não é um teste universal de apendicite. Suspeita de gravidez ectópica, sangramento, massa ou retenção pode exigir exames específicos, sem adiar atendimento por falta de uma manobra íntima."}], "recall": {"question": "Uma hérnia dolorosa e irredutível deve ser reduzida à força durante o treino?", "answer": "Não. É preciso interromper a manipulação e avaliar complicação cirúrgica, especialmente com vômitos, dor persistente, alterações de pele ou instabilidade."}, "sources": ["abd-curso-hernias", "abd-curso-exame", "abd-curso-uro-emergencias", "abd-curso-nice-gestacao"]}, {"id": "a15", "title": "Aorta e isquemia: quando o exame engana", "lead": "Dor muito intensa com parede pouco reativa pode ser um sinal de perigo.", "blocks": [{"title": "Isquemia antes do peritonismo", "text": "Na isquemia mesentérica inicial, o sofrimento da parede intestinal pode produzir dor intensa antes de irritação peritoneal evidente. Considere esse mecanismo em dor desproporcional ao exame, especialmente com fibrilação atrial, aterosclerose, baixo débito ou estado crítico. O padrão clássico não está presente em todos. Ausência de defesa, sangramento digestivo ou elevação do lactato não exclui a doença."}, {"title": "A pergunta que muda a investigação", "text": "Quando a suspeita de isquemia mesentérica é relevante, a angiotomografia deve ser providenciada sem demora evitável. A equipe pondera estabilidade, transporte e necessidade de intervenção imediata; exames laboratoriais não funcionam como autorização para investigar. Peritonite nessa situação pode significar lesão intestinal avançada. No paciente sedado, distensão, intolerância alimentar e deterioração inexplicada podem ser as pistas disponíveis."}, {"title": "Pense em aneurisma", "text": "Dor abdominal ou lombar nova, síncope e choque podem indicar aneurisma de aorta abdominal sintomático ou roto, inclusive sem massa palpável. Não espere a tríade completa. Uma pulsação visível em pessoa magra não confirma aneurisma, e a ausência de sopro não o afasta. Se houver massa dolorosa suspeita, evite palpação profunda repetida para tentar delimitá-la."}, {"title": "Use a imagem sem criar falsa segurança", "text": "Ultrassom à beira-leito pode identificar dilatação aórtica e acelerar o contato vascular. Um exame não diagnóstico não encerra a investigação quando a suspeita persiste; identificar aneurisma não é o mesmo que demonstrar ou excluir ruptura. A escolha da angiotomografia ou do encaminhamento imediato depende da situação clínica e da equipe. Semiologia vascular útil significa reconhecer o risco cedo, não conseguir nomear todos os sinais."}], "recall": {"question": "Dor intensa, fibrilação atrial e lactato normal permitem excluir isquemia?", "answer": "Não. Lactato normal e exame pouco exuberante podem ocorrer no início. A suspeita clínica deve levar à investigação vascular urgente."}, "sources": ["abd-curso-isquemia", "abd-curso-nice-aorta"]}, {"id": "a16", "title": "Pâncreas: dor, posição antálgica e manifestações sistêmicas", "lead": "A postura pode aliviar; ela não confirma pancreatite nem define gravidade.", "blocks": [{"title": "Reconheça a apresentação", "text": "Pancreatite aguda costuma causar dor epigástrica persistente, muitas vezes irradiada para o dorso, com náuseas e vômitos. A dor pode ser difusa e o exame variar de sensibilidade localizada a distensão e íleo. Perfuração, doença biliar, isquemia e síndrome coronariana continuam no diferencial. O pâncreas normal não é um órgão que se espere palpar no exame de rotina."}, {"title": "A posição historicamente descrita", "text": "A anteflexão do tronco pode aliviar desconforto em alguns pacientes. A expressão histórica 'prece maometana' costuma descrever postura genupeitoral ou de flexão associada a dor pancreática em textos de semiologia. Prefira a descrição anatômica e respeitosa da posição adotada. Não obrigue o paciente a ajoelhar-se, a se curvar ou a testar posturas dolorosas. Trata-se de observação antálgica inespecífica, sem valor confirmatório isolado."}, {"title": "Confirme pelos critérios apropriados", "text": "O diagnóstico requer pelo menos dois de três elementos: dor compatível, lipase ou amilase pelo menos três vezes o limite superior de referência, ou imagem característica. Nem toda elevação enzimática é pancreatite, e a intensidade da enzima não mede gravidade. A tomografia não precisa ser imediata quando o diagnóstico está claro e há evolução favorável; incerteza, deterioração ou falta de melhora mudam essa indicação."}, {"title": "Procure a gravidade no organismo", "text": "Hipotensão, hipoxemia, oligúria, alteração de consciência e piora clínica são mais relevantes que equimoses clássicas, que são raras, tardias e inespecíficas. Reavalie respiração, perfusão e balanço volêmico. Pancreatite não significa indicação automática de operação; complicações exigem decisões específicas. A prioridade semiológica é reconhecer repercussão sistêmica e evitar que o rótulo 'pancreatite' esconda outro abdome agudo ou uma complicação associada."}], "recall": {"question": "Alívio ao inclinar o tronco para frente é suficiente para diagnosticar pancreatite?", "answer": "Não. É inespecífico. O diagnóstico depende da combinação de dor, enzimas e/ou imagem, enquanto a gravidade é avaliada pela repercussão clínica e disfunção orgânica."}, "sources": ["abd-curso-atlanta", "abd-curso-acg-pancreatite", "abd-curso-pancreas-dor", "abd-curso-prece-termo"]}, {"id": "a17", "title": "Reavaliação, idosos, gestação e UTI", "lead": "Um exame normal em um momento não garante evolução segura.", "blocks": [{"title": "Faça um exame comparável", "text": "Anote horário, sinais vitais, local da dor, intensidade, resistência da parede, distensão e resposta às intervenções. Reavalie após analgesia e quando houver mudança clínica; não estabeleça um intervalo universal independente da gravidade. Informe quem acompanha e quais mudanças exigem aviso imediato. 'Abdome sem alterações' é menos útil que uma descrição que permita comparar o ponto de dor e a presença de peritonismo."}, {"title": "Populações com sinais atenuados", "text": "Idosos, imunossuprimidos, pessoas com neuropatia ou alterações cognitivas podem ter febre, dor e defesa discretas apesar de doença importante. Imunossupressão não é motivo para esperar sinais clássicos. Na gestação, considere causas obstétricas e não obstétricas, alterações anatômicas e escolha apropriada de imagem. Teste de gravidez e avaliação obstétrica devem ser considerados conforme potencial de gestação e contexto."}, {"title": "O abdome de quem não consegue falar", "text": "Na UTI, sedação, ventilação, bloqueio neuromuscular e opioides modificam a apresentação. Integre distensão, débito de sondas ou drenos, evacuação, sangramento, perfusão, necessidade de suporte e dados de laboratório/imagem. Dieta mal tolerada tem várias causas e não deve ser interpretada isoladamente como isquemia. Ao mesmo tempo, piora inexplicada requer busca ativa por causas abdominais, inclusive não oclusivas."}, {"title": "Pressão intra-abdominal", "text": "Distensão importante com oligúria, piora ventilatória e instabilidade pode motivar avaliação de pressão intra-abdominal. A palpação não mede essa pressão. Em adultos, o consenso define hipertensão intra-abdominal a partir de elevação sustentada ou repetida de 12 mmHg; síndrome compartimental abdominal exige pressão sustentada acima de 20 mmHg associada a nova disfunção orgânica. A aferição exige técnica padronizada e interpretação pela equipe, não inferência pela aparência da barriga."}], "recall": {"question": "Abdome pouco doloroso em imunossuprimido ou sedado exclui emergência?", "answer": "Não. A expressão clínica pode estar reduzida. Evolução, disfunção orgânica, fatores de risco e investigação direcionada ganham importância."}, "sources": ["abd-curso-imunocomprometido", "abd-curso-nice-gestacao", "abd-curso-compartimental", "abd-curso-isquemia"]}, {"id": "a18", "title": "Síntese operacional e prática contínua 360X", "lead": "Conclua cada exame com uma representação do problema e uma decisão verificável.", "blocks": [{"title": "Organize sem decorar um diagnóstico", "text": "Resuma em cinco elementos: estado geral, cronologia, topografia, mecanismo provável e sinais de complicação. Exemplo fictício: adulto com dor progressiva iniciada no centro e agora localizada à direita, sensibilidade focal e estabilidade atual. Isso sustenta investigação de processo inflamatório localizado; não autoriza concluir etiologia apenas pelo resumo. Acrescente a hipótese alternativa perigosa e o dado que ajudará a diferenciá-la."}, {"title": "Escolha a próxima informação", "text": "A pergunta clínica orienta o exame complementar. Ultrassom pode esclarecer vesícula, ascite, bexiga e aorta; tomografia avalia muitas causas e complicações; angiotomografia responde à suspeita vascular. Possibilidade de gestação modifica o percurso. Nenhum exame deve ser pedido apenas para cumprir uma sequência, e instabilidade ou peritonite podem exigir decisões imediatas da equipe antes de investigação extensa."}, {"title": "Treine em quatro passagens", "text": "Primeiro, verbalize o preparo e mostre a posição das mãos em simulador. Depois, explique o mecanismo de um achado, sem consultar o texto. Em seguida, resolva um caso e justifique por que as outras alternativas falham. Por fim, peça feedback de um preceptor sobre comunicação, delicadeza, localização e síntese. Os tutores desta página são roteiros educativos com respostas previstas, não agentes que avaliam pacientes reais."}, {"title": "Revise sem dívida de estudo", "text": "Escolha uma habilidade por sessão e use os cartões em D0, D1, D7, D14 e D30 como convites flexíveis de retomada. Se interromper, volte pelo último caso, sem reiniciar tudo. Ao encerrar, diga: o que aprendi, qual erro evitei e qual técnica vou praticar com supervisão. O marcador de progresso registra estudo; competência clínica exige observação direta, feedback e experiência real em ambiente apropriado."}], "recall": {"question": "Qual é um bom critério de conclusão de uma sessão curta?", "answer": "Conseguir demonstrar uma técnica com segurança, explicar seu significado e limite e resolver um caso relacionado, identificando a próxima habilidade a revisar."}, "sources": ["abd-curso-apendicite", "abd-curso-colecistite", "abd-curso-isquemia", "abd-curso-exame"]}], "syndromes": [{"id": "s01", "title": "Inflamatório e infeccioso", "pattern": "Dor frequentemente progressiva, inicialmente regional ou mal localizada, com sensibilidade focal, náuseas, anorexia e possível febre. Inclui apendicite, colecistite, diverticulite e infecções intra-abdominais; a ausência de febre não exclui.", "mechanism": "Inflamação visceral pode evoluir para irritação do peritônio parietal, tornando a dor mais localizada e sensível ao movimento. Progressão para infecção disseminada ou sepse muda a urgência.", "redFlags": ["Peritonismo difuso ou piora rápida da dor.", "Hipotensão, confusão, hipoperfusão ou outra disfunção orgânica.", "Icterícia com suspeita de infecção biliar.", "Imunossupressão com sintomas discretos e deterioração."], "nextSteps": ["Avaliar estabilidade, oferecer analgesia e realizar exame dirigido.", "Definir hipótese principal e diagnósticos alternativos perigosos.", "Integrar laboratório e imagem apropriados, sem depender de um único sinal.", "Acionar cirurgia e suporte de emergência quando houver complicação ou instabilidade."], "pitfalls": ["Chamar todo Murphy negativo de ausência de colecistite.", "Usar resposta à analgesia para excluir doença cirúrgica.", "Considerar todos os processos inflamatórios equivalentes ou automaticamente operatórios."], "sources": ["abd-curso-apendicite", "abd-curso-colecistite", "abd-curso-diverticulite", "abd-curso-vias-infecciosas"]}, {"id": "s02", "title": "Perfurativo", "pattern": "Dor de início súbito ou piora abrupta, com sensibilidade acentuada, defesa involuntária e possível rigidez difusa. Há apresentações contidas, retroperitoneais ou atípicas sem quadro exuberante.", "mechanism": "Conteúdo de víscera oca e/ou gás extravasam, provocando irritação química e depois contaminação infecciosa. A intensidade e a distribuição variam conforme local, conteúdo e extensão.", "redFlags": ["Choque ou sinais de sepse.", "Peritonismo difuso.", "Dor súbita com piora sistêmica.", "Uso de imunossupressores ou anti-inflamatórios com apresentação pouco típica."], "nextSteps": ["Iniciar suporte e contato cirúrgico imediato conforme gravidade.", "Evitar repetir manobras dolorosas já positivas.", "Solicitar imagem adequada quando puder acrescentar informação sem atrasar intervenção necessária.", "Investigar fonte e necessidade de controle da contaminação pela equipe."], "pitfalls": ["Exigir Jobert positivo ou ar livre radiológico para manter a suspeita.", "Interpretar uma imagem negativa inicial como exclusão universal.", "Confundir todos os casos com indicação de observação: tratamento não operatório depende de seleção especializada."], "sources": ["abd-curso-perfuracao", "abd-curso-imunocomprometido"]}, {"id": "s03", "title": "Obstrutivo", "pattern": "Dor em cólica, distensão, vômitos e redução da eliminação de gases ou fezes. A combinação depende do nível, duração e grau de obstrução; pode haver evacuação no início ou em obstrução parcial.", "mechanism": "Uma barreira mecânica dificulta o trânsito e distende o segmento proximal. Em alça fechada ou estrangulamento, comprometimento vascular pode transformar dor intermitente em contínua e produzir necrose.", "redFlags": ["Dor contínua crescente, peritonismo ou febre com deterioração.", "Hérnia dolorosa e irredutível.", "Hipoperfusão ou instabilidade.", "Sinais de isquemia, alça fechada ou perfuração na investigação."], "nextSteps": ["Examinar cicatrizes, regiões herniárias e estado volêmico.", "Diferenciar hipótese mecânica de íleo sem usar só ausculta.", "Avaliar com imagem, frequentemente tomografia conforme contexto.", "Solicitar avaliação cirúrgica; observação não operatória requer seleção e monitorização."], "pitfalls": ["Afastar obstrução porque o paciente evacuou.", "Diagnosticar íleo somente por ruídos reduzidos.", "Reduzir à força uma hérnia com suspeita de estrangulamento."], "sources": ["abd-curso-bologna", "abd-curso-hernias"]}, {"id": "s04", "title": "Vascular e isquêmico", "pattern": "Dor intensa, por vezes desproporcional ao exame inicial, em contexto embólico, aterosclerótico, trombótico ou de hipoperfusão. Pode haver vômitos, diarreia ou sangue, mas nenhum é obrigatório.", "mechanism": "Oferta insuficiente de sangue ao intestino produz lesão que pode começar antes de sinais peritoneais. Na UTI, a forma não oclusiva pode surgir em baixo fluxo e disfunção sistêmica.", "redFlags": ["Dor desproporcional com fator de risco vascular.", "Deterioração inexplicada em paciente crítico.", "Acidose ou lactato crescente no contexto adequado.", "Peritonite, que pode representar doença avançada."], "nextSteps": ["Manter alta suspeita mesmo com abdome pouco reativo.", "Providenciar angiotomografia sem demora evitável quando indicada.", "Acionar equipes cirúrgica/vascular e suporte simultaneamente.", "Reavaliar perfusão e evolução sem aguardar um biomarcador confirmatório."], "pitfalls": ["Usar lactato normal para excluir.", "Atribuir dor a pancreatite apenas por elevação de enzimas.", "Esperar hematoquezia ou peritonite para investigar."], "sources": ["abd-curso-isquemia"]}, {"id": "s05", "title": "Hemorrágico", "pattern": "Dor abdominal ou lombar associada a palidez, sudorese, síncope, taquicardia, hipotensão ou queda de perfusão. Sangramento pode ser intraperitoneal, retroperitoneal ou intraluminal, com apresentações distintas.", "mechanism": "Perda sanguínea reduz volume circulante; sangue fora dos vasos pode irritar peritônio e produzir dor referida. A hemoglobina inicial pode não refletir a magnitude de uma hemorragia aguda.", "redFlags": ["Colapso circulatório ou síncope.", "Possibilidade de gestação com dor e/ou sangramento.", "Trauma recente, anticoagulação ou massa aórtica suspeita.", "Dor no ombro com quadro compatível e sinais de hipoperfusão."], "nextSteps": ["Priorizar ressuscitação e identificação rápida da fonte.", "Considerar aneurisma roto, gravidez ectópica, lesão esplênica e outras causas.", "Usar ultrassom à beira-leito quando agrega rapidez, reconhecendo limites.", "Acionar equipe capaz de controlar o sangramento e decidir investigação conforme estabilidade."], "pitfalls": ["Esperar equimoses de Cullen ou Grey Turner.", "Excluir hemorragia por hemoglobina inicial aparentemente preservada.", "Interpretar ausência de líquido no ultrassom como exclusão de sangramento retroperitoneal."], "sources": ["abd-curso-nice-aorta", "abd-curso-nice-gestacao", "abd-curso-trauma"]}, {"id": "s06", "title": "Urinário e retroperitoneal", "pattern": "Dor no flanco ou lombar, possível irradiação inguinal, disúria, hematúria, náuseas ou febre. Sensibilidade costovertebral pode estar presente, mas não é obrigatória nem específica.", "mechanism": "Obstrução distende o sistema coletor/ureter; infecção causa inflamação; outras doenças do retroperitônio também provocam dor nessa topografia. Bexiga distendida pode gerar desconforto hipogástrico.", "redFlags": ["Infecção associada a obstrução.", "Anúria, rim único funcional ou deterioração da função renal.", "Dor refratária ou instabilidade.", "Quadro atípico em pessoa com risco de aneurisma."], "nextSteps": ["Investigar sintomas urinários e estado sistêmico.", "Realizar exame lombar delicado e avaliar bexiga quando indicado.", "Solicitar urina, função renal e imagem conforme hipótese.", "Buscar urologia urgente quando houver obstrução infectada ou ameaça à função."], "pitfalls": ["Considerar Giordano positivo sinônimo de pielonefrite.", "Afastar cálculo por ausência de hematúria.", "Tratar sepse obstrutiva apenas com analgesia ou esperar resposta prolongada sem avaliar drenagem."], "sources": ["abd-curso-eau", "abd-curso-uro-emergencias", "abd-curso-nice-aorta"]}, {"id": "s07", "title": "Mimetizadores, parede e causas extra-abdominais", "pattern": "Dor abdominal pode acompanhar síndrome coronariana, pneumonia basal, alterações metabólicas, dor da parede, herpes-zóster, doença testicular ou ginecológica. 'Mimetizador' não significa benigno.", "mechanism": "Dor referida, inflamação próxima ao diafragma, distúrbios metabólicos e lesões da parede podem reproduzir sintomas de vísceras. Mais de um processo pode coexistir.", "redFlags": ["Dor epigástrica com sudorese, dispneia ou risco cardiovascular.", "Hipoxemia, febre ou achados pulmonares.", "Possibilidade de gestação ou dor testicular aguda.", "Alteração de consciência, respiração anormal ou descompensação metabólica."], "nextSteps": ["Ampliar história e exame conforme as pistas, incluindo tórax, circulação e glicemia quando pertinente.", "Considerar eletrocardiograma e investigação cardíaca em apresentação compatível.", "Avaliar causas ginecológicas, urinárias ou genitais com consentimento e urgência apropriada.", "Rever a hipótese se os achados não se encaixarem na evolução."], "pitfalls": ["Rotular ansiedade antes de avaliar causas orgânicas relevantes.", "Usar Carnett para excluir toda doença visceral.", "Encerrar a investigação quando um único exame vem normal."], "sources": ["abd-curso-gi", "abd-curso-exame", "abd-curso-uro-emergencias", "abd-curso-nice-gestacao"]}], "cases": [{"id": "c01", "title": "Hipocôndrio direito sem Murphy", "stem": "Caso fictício. Mulher de 72 anos, com diabetes, apresenta dor persistente no hipocôndrio direito há 18 horas, náuseas e febre. Há sensibilidade local, mas ela não interrompe a inspiração durante a palpação. Está hemodinamicamente estável.", "question": "Qual é a interpretação mais adequada?", "options": [{"text": "O Murphy negativo reduz a necessidade de investigar doença vesicular.", "correct": false, "feedback": "A ausência desse sinal não tem capacidade suficiente para excluir colecistite. Idade, contexto metabólico e evolução persistente impedem uma conclusão tranquilizadora isolada."}, {"text": "A hipótese biliar permanece e deve ser integrada a laboratório e ultrassom.", "correct": true, "feedback": "A combinação de história, sinais inflamatórios e imagem é necessária. O exame focal orienta a investigação, mas nenhum achado sozinho confirma ou exclui colecistite."}, {"text": "A dor subcostal, mesmo sem parada inspiratória, deve ser registrada como Murphy positivo.", "correct": false, "feedback": "Sensibilidade local não é equivalente à interrupção inspiratória característica. Registre o achado observado, sem converter dor genérica em sinal positivo."}, {"text": "A melhor etapa é repetir Murphy várias vezes antes de solicitar imagem.", "correct": false, "feedback": "Repetir uma manobra dolorosa tem pouco ganho quando a suspeita já está estabelecida. Investigação e reavaliação são mais úteis."}], "takeaway": "TEMI e plantão: um sinal negativo pode ser insuficiente para afastar doença. Descreva a técnica real e mantenha a hipótese coerente com a evolução.", "sources": ["abd-curso-colecistite"]}, {"id": "c02", "title": "Analgesia durante a investigação", "stem": "Caso fictício. Homem de 29 anos chega com dor abdominal intensa e suspeita de apendicite. Está estável e aguarda avaliação cirúrgica. Um colega sugere adiar analgesia até a chegada do cirurgião.", "question": "Qual atitude melhor combina conforto e qualidade diagnóstica?", "options": [{"text": "Adiar o alívio da dor até concluir todos os sinais apendiculares.", "correct": false, "feedback": "Sofrimento não melhora a avaliação. A preocupação com mascaramento não justifica adiar analgesia apropriada durante a investigação."}, {"text": "Oferecer analgesia e encerrar a investigação se a dor melhorar.", "correct": false, "feedback": "Melhora sintomática não exclui doença cirúrgica. É preciso manter a avaliação etiológica e documentar a evolução."}, {"text": "Oferecer analgesia, registrar o momento e reavaliar junto da investigação.", "correct": true, "feedback": "A evidência disponível não demonstra aumento de erro diagnóstico com analgesia opioide nos estudos incluídos. Monitorização e reexame mantêm a interpretação contextual."}, {"text": "Substituir a analgesia por repetição do exame para identificar o ponto exato.", "correct": false, "feedback": "Repetição de estímulos dolorosos aumenta sofrimento e não substitui tratamento adequado da dor nem avaliação seriada criteriosa."}], "takeaway": "Regra prática: analgesia e diagnóstico avançam juntos. A resposta ao analgésico é uma observação de evolução, não um teste de exclusão.", "sources": ["abd-curso-analgesia"]}, {"id": "c03", "title": "Dor grande, exame discreto", "stem": "Caso fictício. Homem de 78 anos com fibrilação atrial refere dor abdominal intensa de início recente. O abdome é pouco doloroso à palpação, sem defesa clara. O lactato inicial está no intervalo de referência.", "question": "Qual hipótese e próximo passo merecem prioridade?", "options": [{"text": "Investigar isquemia mesentérica urgentemente, considerando angiotomografia.", "correct": true, "feedback": "A discordância entre dor e exame, associada ao risco embólico, é um alerta. Lactato normal não exclui isquemia inicial e não deve atrasar imagem apropriada."}, {"text": "Reclassificar como dor funcional pela ausência de defesa.", "correct": false, "feedback": "Ausência de peritonismo não demonstra origem funcional; pode ocorrer antes de lesão transmural. O risco vascular muda a interpretação."}, {"text": "Esperar elevação do lactato antes de solicitar estudo vascular.", "correct": false, "feedback": "Nenhum biomarcador isolado é suficientemente sensível para autorizar ou negar a investigação. Esperar alteração pode perder tempo crítico."}, {"text": "Priorizar obstrução mecânica apenas pelo caráter intenso da dor.", "correct": false, "feedback": "Obstrução entra no diferencial, mas a combinação apresentada exige excluir isquemia sem demora. Intensidade isolada não distingue mecanismos."}], "takeaway": "A parede pode parecer relativamente tranquila enquanto o intestino sofre. Dor desproporcional deve acionar raciocínio vascular.", "sources": ["abd-curso-isquemia"]}, {"id": "c04", "title": "Jobert ausente, peritonismo presente", "stem": "Caso fictício. Mulher de 54 anos, em uso frequente de anti-inflamatórios, apresenta dor epigástrica súbita, agora difusa, com resistência involuntária e piora ao mínimo movimento. A macicez hepática permanece perceptível.", "question": "Como interpretar a percussão?", "options": [{"text": "A macicez preservada torna perfuração improvável o suficiente para observação simples.", "correct": false, "feedback": "O sinal de Jobert tem limitações; sua ausência não neutraliza um quadro de possível perfuração com peritonismo."}, {"text": "O sinal confirma uma perfuração contida.", "correct": false, "feedback": "A percussão não permite classificar perfuração como contida. Essa inferência exige investigação e avaliação especializada."}, {"text": "É necessário percutir com mais força para tornar o exame conclusivo.", "correct": false, "feedback": "Mais força não torna o teste confiável e pode causar dor. Já há informação clínica suficiente para justificar avaliação urgente."}, {"text": "Perfuração continua no diferencial prioritário e exige avaliação cirúrgica.", "correct": true, "feedback": "O início súbito e o peritonismo têm implicação urgente. Imagem é escolhida conforme estabilidade e deve ajudar, sem atrasar intervenção necessária."}], "takeaway": "Um epônimo ausente não deve rebaixar a gravidade de uma síndrome clinicamente preocupante.", "sources": ["abd-curso-perfuracao"]}, {"id": "c05", "title": "Evacuou, mas continua distendido", "stem": "Caso fictício. Homem de 61 anos, operado do abdome no passado, apresenta cólicas, vômitos e distensão. Evacuou pequena quantidade pela manhã. Agora a dor fica mais contínua.", "question": "Qual conclusão é a mais segura?", "options": [{"text": "A evacuação recente exclui obstrução mecânica completa ou parcial.", "correct": false, "feedback": "Conteúdo distal ainda pode ser eliminado, sobretudo no início, e obstrução parcial permite algum trânsito. A história não exclui o mecanismo."}, {"text": "Obstrução permanece possível; mudança para dor contínua pede busca de complicação.", "correct": true, "feedback": "Cirurgia prévia é contexto relevante para aderências, mas hérnias e outras causas também devem ser examinadas. Dor contínua crescente aumenta preocupação com comprometimento vascular."}, {"text": "Aderência pode ser confirmada apenas pela cicatriz.", "correct": false, "feedback": "A cicatriz revela antecedente, não a causa atual. Imagem e avaliação clínica ajudam a definir nível, mecanismo e sinais de complicação."}, {"text": "Ausculta com ruídos presentes permitiria dispensar imagem.", "correct": false, "feedback": "Ruídos podem existir em obstrução e não excluem isquemia. A investigação deve responder ao conjunto do caso."}], "takeaway": "Pergunte sobre fezes e gases, mas não use uma evacuação isolada como certificado de trânsito livre.", "sources": ["abd-curso-bologna", "abd-curso-hernias"]}, {"id": "c06", "title": "Cólica com febre e obstrução", "stem": "Caso fictício. Mulher de 47 anos apresenta dor no flanco, febre, calafrios e taquicardia. O exame provoca dor costovertebral; o ultrassom mostra hidronefrose. Há suspeita de cálculo obstrutivo.", "question": "Qual é o ponto decisivo?", "options": [{"text": "Giordano positivo define pielonefrite sem necessidade de avaliar obstrução.", "correct": false, "feedback": "O sinal é inespecífico e não distingue uma infecção sem obstrução de uma emergência que exige drenagem."}, {"text": "A hidronefrose exige apenas controle da dor enquanto se aguarda a cultura.", "correct": false, "feedback": "Infecção associada a obstrução pode evoluir rapidamente. A cultura orienta ajuste, mas não é motivo para adiar tratamento e avaliação de descompressão."}, {"text": "O quadro pode representar obstrução infectada e precisa de urologia urgente.", "correct": true, "feedback": "Drenagem do sistema coletor pode ser necessária junto do tratamento da infecção. O risco decorre da combinação de obstrução e sinais sistêmicos."}, {"text": "A ausência de hematúria afastaria o cálculo e tornaria o quadro menos urgente.", "correct": false, "feedback": "Cálculo pode ocorrer sem hematúria. A urgência permanece sustentada pela obstrução com suspeita de infecção."}], "takeaway": "Obstrução + infecção é uma combinação diferente de cólica simples. O exame local não substitui a avaliação da fonte.", "sources": ["abd-curso-eau"]}, {"id": "c07", "title": "Ascite sem dor na internação", "stem": "Caso fictício. Homem de 58 anos com cirrose e ascite é internado por piora renal e confusão. Está afebril e não tem dor abdominal. A macicez muda com o decúbito.", "question": "Qual interpretação evita uma omissão relevante?", "options": [{"text": "A ausência de dor torna peritonite bacteriana espontânea suficientemente improvável.", "correct": false, "feedback": "Infecção do líquido ascítico pode ocorrer sem sinais clássicos, inclusive com encefalopatia ou disfunção renal."}, {"text": "Macicez móvel indica que o líquido é estéril.", "correct": false, "feedback": "A manobra indica distribuição de líquido móvel, sem informar sua composição ou presença de infecção."}, {"text": "É preciso um piparote positivo antes de considerar análise do líquido.", "correct": false, "feedback": "Outro sinal físico não é requisito para paracentese diagnóstica quando há indicação clínica."}, {"text": "A internação aguda em cirrose com ascite exige considerar prontamente paracentese diagnóstica.", "correct": true, "feedback": "A investigação de peritonite bacteriana espontânea deve ocorrer mesmo sem dor ou febre. Análise celular e cultura fornecem informação que o exame físico não oferece."}], "takeaway": "Ascite é um achado físico; infecção é uma pergunta diferente. Deterioração renal ou neurológica pode ser sua manifestação.", "sources": ["abd-curso-aasld", "abd-curso-easl"]}, {"id": "c08", "title": "Dor lombar, síncope e aorta", "stem": "Caso fictício. Homem de 74 anos, ex-tabagista, apresenta dor abdominal e lombar súbita, episódio de síncope e pressão baixa. Não há massa palpável nem sopro abdominal evidente.", "question": "Qual é a melhor leitura semiológica?", "options": [{"text": "Aneurisma roto continua possível e deve motivar avaliação vascular imediata.", "correct": true, "feedback": "A tríade clássica é incompleta em muitos casos. Ultrassom à beira-leito e contato vascular podem acelerar a decisão, conforme recursos e estabilidade."}, {"text": "Ausência de massa e sopro exclui uma origem aórtica.", "correct": false, "feedback": "A sensibilidade do exame físico é insuficiente. Obesidade, anatomia e apresentação clínica podem ocultar esses achados."}, {"text": "A palpação profunda repetida é a forma mais rápida de confirmar diâmetro aórtico.", "correct": false, "feedback": "Palpação não fornece medida confiável e repetir compressões dolorosas não é útil nesse contexto. Priorize avaliação e imagem adequadas."}, {"text": "Dor lombar deve direcionar inicialmente apenas para litíase urinária.", "correct": false, "feedback": "Litíase é diferencial, mas síncope e hipotensão em pessoa com risco vascular obrigam a considerar hemorragia aórtica."}], "takeaway": "Diante de colapso com dor abdominal ou lombar, procure a doença perigosa mesmo que o sinal esperado não esteja presente.", "sources": ["abd-curso-nice-aorta"]}, {"id": "c09", "title": "Dor pélvica com apresentação incompleta", "stem": "Caso fictício. Mulher de 32 anos refere dor no baixo ventre e tontura. Não relata atraso menstrual e não sabe se pode estar grávida. Há sensibilidade abdominal; sangramento vaginal não foi observado.", "question": "Qual passo é mais apropriado?", "options": [{"text": "A ausência de atraso informado torna gravidez ectópica remota demais para investigar.", "correct": false, "feedback": "História menstrual incerta e apresentação atípica não excluem gestação. A ausência de fatores clássicos também não afasta ectópica."}, {"text": "Considerar teste de gravidez e avaliação urgente conforme estabilidade e suspeita.", "correct": true, "feedback": "Dor abdominal em pessoa com potencial de gestação exige essa possibilidade no raciocínio. Tontura ou sinais de hipoperfusão tornam a avaliação mais urgente."}, {"text": "O diagnóstico pode ser feito pela localização da dor à palpação.", "correct": false, "feedback": "Topografia não identifica implantação da gestação. Avaliação laboratorial, ultrassonográfica e clínica deve ser integrada."}, {"text": "Exame ginecológico normal permitiria encerrar a investigação.", "correct": false, "feedback": "Achados normais ou pouco expressivos não excluem gravidez ectópica. A evolução e os métodos apropriados continuam necessários."}], "takeaway": "Perguntar sobre gestação é parte do exame abdominal. Não é necessário esperar a tríade completa de dor, atraso e sangramento.", "sources": ["abd-curso-nice-gestacao"]}, {"id": "c10", "title": "Dor focal e Carnett", "stem": "Caso fictício. Homem de 40 anos apresenta dor localizada em pequeno ponto da parede há semanas, sem sintomas sistêmicos. A dor persiste quando ele contrai suavemente a musculatura abdominal. Não há instabilidade ou peritonismo.", "question": "O que o achado permite dizer?", "options": [{"text": "Está demonstrado que não existe doença visceral concomitante.", "correct": false, "feedback": "Um teste que favorece origem parietal não elimina todas as causas viscerais nem dispensa contexto e seguimento."}, {"text": "O resultado é irrelevante, pois toda dor abdominal vem das vísceras.", "correct": false, "feedback": "Parede, nervos, músculos, hérnias e hematomas podem produzir dor. Ignorar essa camada leva a investigação e tratamentos inadequados."}, {"text": "O resultado favorece dor da parede, a ser integrado à história e ao exame local.", "correct": true, "feedback": "Persistência ou aumento com contração pode apoiar origem parietal em contexto apropriado. É necessário examinar hérnias, alterações cutâneas e outros achados."}, {"text": "A melhor confirmação é repetir a contração até produzir dor máxima.", "correct": false, "feedback": "Intensificar sofrimento não confirma etiologia. Uma resposta clara e tolerável basta para acrescentar informação."}], "takeaway": "Carnett ajuda a mudar a camada do raciocínio: parede também dói. Ele não é um selo universal de benignidade.", "sources": ["abd-curso-exame", "abd-curso-inspecao"]}, {"id": "c11", "title": "Postura antálgica no epigástrio", "stem": "Caso fictício. Mulher de 45 anos tem dor epigástrica com irradiação dorsal e prefere sentar-se inclinada para frente. A lipase está discretamente acima do limite de referência, sem chegar a três vezes esse limite.", "question": "Qual interpretação é adequada?", "options": [{"text": "A posição antálgica confirma pancreatite independentemente dos demais dados.", "correct": false, "feedback": "O alívio postural é inespecífico. A descrição clássica não substitui os critérios diagnósticos nem a avaliação de causas alternativas."}, {"text": "A elevação discreta de lipase mede a gravidade da pancreatite.", "correct": false, "feedback": "Magnitude enzimática não mede gravidade e elevação discreta pode ter outras causas. O contexto e a repercussão orgânica importam."}, {"text": "É obrigatório forçar a posição genupeitoral para completar o exame.", "correct": false, "feedback": "Posturas antálgicas são observadas, não impostas como teste confirmatório. Deve-se respeitar o conforto e evitar quedas ou piora da dor."}, {"text": "Pancreatite permanece uma hipótese, mas os dados fornecidos não bastam para confirmação pelos critérios usuais.", "correct": true, "feedback": "É necessário reunir pelo menos dois dos três critérios: dor compatível, enzimas ≥3 vezes o limite superior ou imagem característica. Deve-se investigar conforme o cenário, incluindo diagnósticos alternativos."}], "takeaway": "A posição ajuda a descrever a dor; os critérios confirmam o diagnóstico. Gravidade pertence à evolução clínica e à disfunção orgânica.", "sources": ["abd-curso-atlanta", "abd-curso-acg-pancreatite", "abd-curso-pancreas-dor"]}, {"id": "c12", "title": "Peritonismo já evidente", "stem": "Caso fictício. Homem de 50 anos tem dor difusa intensa, resistência involuntária e piora ao mínimo movimento. Um examinador já observou dor à descompressão. Três estudantes querem repetir Blumberg.", "question": "Qual conduta de ensino é a melhor?", "options": [{"text": "Evitar repetição dolorosa, compartilhar o achado e priorizar assistência e discussão clínica.", "correct": true, "feedback": "O paciente não deve ser submetido a sofrimento repetido para confirmar um achado já suficiente. Demonstração em simulador e raciocínio supervisionado preservam aprendizado."}, {"text": "Repetir em todos os quadrantes para permitir que cada estudante registre o próprio sinal.", "correct": false, "feedback": "A repetição tem baixo ganho e pode aumentar dor e ansiedade. A necessidade de documentação não justifica manobras desnecessárias."}, {"text": "Aplicar pressão maior porque sinais fortes são mais confiáveis.", "correct": false, "feedback": "Força maior pode provocar dor inespecífica e não melhora automaticamente a acurácia."}, {"text": "Adiar avaliação cirúrgica até terminar a aula prática.", "correct": false, "feedback": "Peritonismo e contexto clínico podem exigir intervenção urgente. O ensino deve acompanhar a prioridade assistencial."}], "takeaway": "A arte do exame inclui saber parar. Um sinal deve responder a uma pergunta clínica, não a uma exigência de espetáculo.", "sources": ["abd-curso-exame", "abd-curso-perfuracao", "abd-curso-analgesia"]}, {"id": "c13", "title": "Baço não palpável", "stem": "Caso fictício. Mulher de 36 anos com citopenias e suspeita clínica de esplenomegalia não tem baço palpável no primeiro exame. Não apresenta dor aguda nem instabilidade.", "question": "Como prosseguir?", "options": [{"text": "Registrar baço normal, pois não foi palpado.", "correct": false, "feedback": "'Não palpável' é um achado; 'normal' é conclusão mais ampla que o exame não garante. Sensibilidade da palpação é limitada."}, {"text": "Revisar a técnica com delicadeza e considerar ultrassom conforme a suspeita.", "correct": true, "feedback": "A posição, trajetória da mão e biotipo influenciam a palpação. A imagem pode esclarecer tamanho quando a hipótese clínica persiste."}, {"text": "Comprimir vigorosamente o hipocôndrio esquerdo até sentir uma borda.", "correct": false, "feedback": "Insistência vigorosa não é uma técnica aceitável, especialmente sobre órgão potencialmente frágil."}, {"text": "Usar somente a presença de macicez em Traube para definir volume esplênico.", "correct": false, "feedback": "A percussão tem interferências e não mede volume. Deve ser integrada à palpação e aos métodos apropriados."}], "takeaway": "Descreva o limite da observação. 'Não palpável' não é sinônimo de ausência de esplenomegalia.", "sources": ["abd-curso-baco", "abd-curso-stanford-organos"]}, {"id": "c14", "title": "Sons intestinais e certeza excessiva", "stem": "Caso fictício. Paciente no pós-operatório apresenta distensão e desconforto. Após escutar poucos segundos, o examinador registra 'íleo confirmado por ausência de ruídos'.", "question": "Qual é o principal problema?", "options": [{"text": "A ausculta foi feita antes da palpação.", "correct": false, "feedback": "Essa é uma sequência didática habitual. A falha principal é atribuir diagnóstico definitivo a uma observação breve e isolada."}, {"text": "Todo pós-operatório com distensão exige diagnóstico de obstrução mecânica.", "correct": false, "feedback": "Íleo, medicamentos, alterações metabólicas e complicações mecânicas são possibilidades; a distinção exige contexto."}, {"text": "A observação curta e a ausculta isolada não permitem confirmar o mecanismo.", "correct": true, "feedback": "É preciso descrever duração e achados, revisar dor, trânsito, medicamentos e evolução, e usar investigação quando indicada."}, {"text": "Ouvir um ruído posteriormente descartaria complicação abdominal.", "correct": false, "feedback": "Presença de sons não exclui obstrução, isquemia ou outra complicação. O exame deve ser integrado."}], "takeaway": "Sons são um componente do exame, não um laudo do intestino. A certeza deve ser proporcional à informação obtida.", "sources": ["abd-curso-exame", "abd-curso-bologna", "abd-curso-sons-estudo"]}, {"id": "c15", "title": "Imunossupressão e sinais discretos", "stem": "Caso fictício. Homem de 67 anos, transplantado e em imunossupressão, tem desconforto abdominal novo, recusa alimentar e piora renal. Está sem febre e com pouca defesa à palpação.", "question": "Qual abordagem reduz o risco de atraso?", "options": [{"text": "A ausência de febre afasta infecção intra-abdominal relevante.", "correct": false, "feedback": "Imunossupressão pode reduzir a resposta febril. Deterioração orgânica e mudança clínica precisam ser valorizadas."}, {"text": "A intensidade da defesa permite classificar o quadro como leve.", "correct": false, "feedback": "A resposta da parede pode ser atenuada e não reflete necessariamente a extensão da doença."}, {"text": "O exame abdominal pode ser dispensado porque a imagem sempre resolve.", "correct": false, "feedback": "Exame e história continuam úteis para direcionar a avaliação. A limitação dos sinais pede integração, não abandono da semiologia."}, {"text": "Manter suspeita ampliada e realizar avaliação dirigida, com baixo limiar para investigação apropriada.", "correct": true, "feedback": "Sintomas discretos em paciente vulnerável podem acompanhar doença grave. Evolução, exame global e métodos complementares devem ser combinados prontamente."}], "takeaway": "O mesmo achado negativo tem significado diferente em populações distintas. A ausência de exuberância não deve gerar falsa segurança.", "sources": ["abd-curso-imunocomprometido"]}, {"id": "c16", "title": "Abdome tenso na UTI", "stem": "Caso fictício. Paciente adulto sedado na UTI apresenta distensão progressiva, piora da mecânica ventilatória e oligúria. A pressão intra-abdominal, medida por técnica padronizada, permanece em 24 mmHg, com nova disfunção orgânica compatível.", "question": "Qual interpretação é a mais adequada?", "options": [{"text": "O conjunto é compatível com síndrome compartimental abdominal e exige avaliação urgente.", "correct": true, "feedback": "Em adultos, pressão sustentada acima de 20 mmHg associada a nova disfunção orgânica preenche a definição de consenso. A causa e o manejo devem ser avaliados pela equipe."}, {"text": "A palpação de abdome tenso, sozinha, teria sido suficiente para confirmar o diagnóstico.", "correct": false, "feedback": "A percepção da parede não mede pressão. É necessária aferição adequada e relação com disfunção orgânica."}, {"text": "Qualquer pressão acima de 12 mmHg significa síndrome compartimental.", "correct": false, "feedback": "Esse valor se relaciona à hipertensão intra-abdominal; síndrome compartimental exige pressão mais alta e nova disfunção orgânica."}, {"text": "Sedação profunda torna desnecessária a reavaliação abdominal.", "correct": false, "feedback": "Sedação reduz expressão de dor e aumenta a importância de sinais indiretos, evolução e medidas objetivas."}], "takeaway": "Diferencie distensão, hipertensão intra-abdominal e síndrome compartimental. Aparência, pressão e repercussão orgânica são informações distintas.", "sources": ["abd-curso-compartimental"]}], "flashcards": [{"id": "f01", "question": "Qual decisão vem antes de completar o exame abdominal?", "answer": "Se o paciente está estável e se há tempo para exame completo ou necessidade de suporte e avaliação urgente.", "topic": "seguranca"}, {"id": "f02", "question": "Onde iniciar a palpação quando há dor localizada?", "answer": "Em região menos dolorosa e distante do ponto referido, avançando com delicadeza.", "topic": "tecnica"}, {"id": "f03", "question": "Braços atrás da cabeça favorecem o relaxamento da parede?", "answer": "Não. Podem tensionar a musculatura; prefira braços ao lado do corpo no exame de rotina.", "topic": "preparo"}, {"id": "f04", "question": "É necessário esperar diagnóstico definitivo para aliviar a dor?", "answer": "Não. Analgesia apropriada pode acompanhar a investigação, com registro e reavaliação.", "topic": "seguranca"}, {"id": "f05", "question": "Como costuma ser percebida a dor visceral?", "answer": "Mais difusa e mal localizada, podendo acompanhar distensão ou contração; é um padrão, não uma regra absoluta.", "topic": "dor"}, {"id": "f06", "question": "O que favorece dor de origem parietal peritoneal?", "answer": "Localização mais precisa e piora com movimento, tosse ou contato, no contexto clínico adequado.", "topic": "dor"}, {"id": "f07", "question": "Direita e esquerda no mapa abdominal são de quem?", "answer": "Do paciente, independentemente de onde o examinador está.", "topic": "anatomia"}, {"id": "f08", "question": "Quais são as três regiões centrais do mapa de nove regiões?", "answer": "Epigástrio, região umbilical e hipogástrio, de cima para baixo.", "topic": "anatomia"}, {"id": "f09", "question": "Qual é a sequência didática habitual do exame abdominal?", "answer": "Inspeção, ausculta, percussão e palpação, adaptada à gravidade e ao conforto.", "topic": "tecnica"}, {"id": "f10", "question": "Auscultar depois de tocar o abdome invalida automaticamente o exame?", "answer": "Não. A sequência é uma convenção útil; o contexto e a técnica importam, e estudos em grupos selecionados questionam efeito relevante do toque sobre a frequência dos sons.", "topic": "ausculta"}, {"id": "f11", "question": "Alguns segundos sem sons confirmam íleo?", "answer": "Não. A amostra curta e a ausculta isolada não estabelecem o diagnóstico.", "topic": "ausculta"}, {"id": "f12", "question": "Sons presentes excluem obstrução intestinal?", "answer": "Não. A obstrução pode ter sons presentes, aumentados ou reduzidos conforme evolução.", "topic": "ausculta"}, {"id": "f13", "question": "O que o timpanismo sugere à percussão?", "answer": "Predomínio de gás sob a área examinada, com interpretação dependente do contexto.", "topic": "percussao"}, {"id": "f14", "question": "O que pode produzir macicez abdominal?", "answer": "Órgão sólido, líquido ou massa; o som não define sozinho a causa.", "topic": "percussao"}, {"id": "f15", "question": "O que se descreve classicamente como sinal de Jobert?", "answer": "Perda da macicez hepática, uma pista possível de gás interposto, sem confirmar ou excluir perfuração isoladamente.", "topic": "eponimos"}, {"id": "f16", "question": "Como descrever defesa para reduzir ambiguidade?", "answer": "Informar localização, extensão, intensidade e se a resistência cede com relaxamento, além da dor associada.", "topic": "palpacao"}, {"id": "f17", "question": "Por que não repetir Blumberg várias vezes?", "answer": "Porque uma resposta já clara pode bastar, e repetição dolorosa agrega sofrimento com pouco ganho informativo.", "topic": "seguranca"}, {"id": "f18", "question": "O que caracteriza o Murphy clínico clássico?", "answer": "Interrupção súbita da inspiração por dor durante palpação subcostal direita direcionada à projeção vesicular.", "topic": "biliar"}, {"id": "f19", "question": "Murphy negativo exclui colecistite?", "answer": "Não. História, inflamação e imagem devem ser integradas.", "topic": "biliar"}, {"id": "f20", "question": "Murphy clínico e ultrassonográfico são o mesmo procedimento?", "answer": "Não. Um usa palpação; o outro localiza a vesícula na imagem e testa dor com o transdutor.", "topic": "biliar"}, {"id": "f21", "question": "Qual combinação é associada ao sinal de Courvoisier?", "answer": "Icterícia com vesícula aumentada e indolor; sugere investigação de obstrução distal, com exceções e sem confirmar neoplasia.", "topic": "biliar"}, {"id": "f22", "question": "Borda hepática palpável sempre indica hepatomegalia?", "answer": "Não. Biotipo, posição do diafragma e variações anatômicas influenciam a palpação.", "topic": "figado"}, {"id": "f23", "question": "Baço não palpável exclui esplenomegalia?", "answer": "Não. Persistindo suspeita, técnica e imagem devem ser consideradas.", "topic": "baco"}, {"id": "f24", "question": "Que mudança caracteriza macicez móvel?", "answer": "O limite de macicez se desloca após mudança de decúbito e redistribuição do líquido.", "topic": "ascite"}, {"id": "f25", "question": "Macicez móvel informa se há infecção no líquido?", "answer": "Não. A composição e infecção exigem investigação específica do líquido.", "topic": "ascite"}, {"id": "f26", "question": "Cirrose com ascite em internação aguda exige pensar em qual procedimento diagnóstico?", "answer": "Paracentese diagnóstica para investigar infecção, mesmo sem febre ou dor, conforme avaliação assistencial.", "topic": "ascite"}, {"id": "f27", "question": "Giordano positivo identifica necessariamente pielonefrite?", "answer": "Não. Sensibilidade costovertebral é inespecífica e pode acompanhar outras causas.", "topic": "urinario"}, {"id": "f28", "question": "Qual combinação transforma a litíase em emergência infecciosa?", "answer": "Obstrução do sistema urinário associada a infecção ou sepse, com necessidade de avaliação urgente de drenagem.", "topic": "urinario"}, {"id": "f29", "question": "Evacuação recente afasta obstrução?", "answer": "Não. Pode ocorrer no início ou em obstrução parcial.", "topic": "obstrucao"}, {"id": "f30", "question": "Dor antes em cólica que se torna contínua exige pensar em quê?", "answer": "Complicação como isquemia ou estrangulamento, entre outras causas; exige reavaliação.", "topic": "obstrucao"}, {"id": "f31", "question": "Uma hérnia dolorosa com suspeita de estrangulamento deve ser reduzida à força?", "answer": "Não. Requer avaliação cirúrgica e manipulação criteriosa.", "topic": "parede"}, {"id": "f32", "question": "O que um Carnett positivo pode favorecer?", "answer": "Origem na parede abdominal em contexto apropriado, sem excluir toda doença visceral.", "topic": "parede"}, {"id": "f33", "question": "Dor desproporcional ao exame levanta qual alerta?", "answer": "Isquemia mesentérica, especialmente com risco vascular, embora o padrão não seja universal.", "topic": "vascular"}, {"id": "f34", "question": "Lactato normal exclui isquemia mesentérica inicial?", "answer": "Não.", "topic": "vascular"}, {"id": "f35", "question": "Ausência de massa pulsátil exclui aneurisma aórtico roto?", "answer": "Não. Dor abdominal/lombar com síncope ou choque exige considerar essa hipótese.", "topic": "vascular"}, {"id": "f36", "question": "Alívio da dor ao inclinar-se para frente confirma pancreatite?", "answer": "Não. É uma observação antálgica inespecífica.", "topic": "pancreas"}, {"id": "f37", "question": "Quais são os três componentes dos critérios de pancreatite aguda?", "answer": "Dor compatível; lipase ou amilase ≥3 vezes o limite superior; imagem característica. São necessários pelo menos dois.", "topic": "pancreas"}, {"id": "f38", "question": "Qual achado pesa mais na gravidade: enzima alta ou nova disfunção orgânica?", "answer": "Nova disfunção orgânica e evolução clínica; o valor da enzima não mede gravidade.", "topic": "pancreas"}, {"id": "f39", "question": "A partir de que valor se define hipertensão intra-abdominal no adulto?", "answer": "Pressão intra-abdominal sustentada ou repetida ≥12 mmHg, medida adequadamente.", "topic": "uti"}, {"id": "f40", "question": "O que diferencia síndrome compartimental abdominal de hipertensão intra-abdominal?", "answer": "Pressão sustentada >20 mmHg associada a nova disfunção orgânica; palpação isolada não confirma.", "topic": "uti"}], "checklist": [{"id": "k01", "text": "Na simulação, verbalizar avaliação de estabilidade e indicar quais sinais interromperiam o exame prolongado."}, {"id": "k02", "text": "Apresentar-se, explicar a sequência, obter consentimento e combinar como avisar desconforto."}, {"id": "k03", "text": "Demonstrar higiene das mãos, privacidade e exposição adequada sem exposição íntima desnecessária."}, {"id": "k04", "text": "Posicionar a pessoa confortavelmente, com braços ao lado e apoios conforme necessidade."}, {"id": "k05", "text": "Reconstruir cronologia, topografia, migração/irradiação, associados e fatores de risco da dor."}, {"id": "k06", "text": "Identificar os quatro quadrantes e distinguir localização da hipótese etiológica."}, {"id": "k07", "text": "Descrever inspeção e comportamento antes de nomear doenças ou epônimos."}, {"id": "k08", "text": "Demonstrar ausculta suave e explicar por que sons isolados não confirmam nem excluem obstrução."}, {"id": "k09", "text": "Demonstrar percussão comparativa leve e reconhecer o limite entre macicez e timpanismo."}, {"id": "k10", "text": "Mostrar palpação superficial começando longe da dor e observando a resposta do paciente."}, {"id": "k11", "text": "Diferenciar resistência que cede ao relaxamento de defesa persistente, descrevendo o achado."}, {"id": "k12", "text": "Demonstrar uma técnica dirigida apropriada à hipótese, explicando seu resultado e suas limitações."}, {"id": "k13", "text": "Identificar situações em que não se deve insistir em palpação profunda, descompressão ou redução de hérnia."}, {"id": "k14", "text": "Lembrar causas vasculares, urinárias, gestacionais, genitais e extra-abdominais conforme o caso."}, {"id": "k15", "text": "Concluir com síntese, hipóteses perigosas, investigação necessária e plano de reavaliação."}, {"id": "k16", "text": "Registrar uma habilidade aprendida e uma lacuna para feedback supervisionado, sem usar a pontuação como certificado clínico."}], "tutors": [{"id": "t01", "name": "Tutor de Técnica e Delicadeza", "role": "Roteiro educativo de execução do exame", "goal": "Transformar conhecimento verbal em posição, movimento e comunicação corretos, usando simulação e supervisão.", "steps": [{"question": "Você vai começar um exame em paciente com dor. Quais ações precedem o primeiro toque?", "answer": "Avaliar estabilidade, apresentar-se, explicar, obter consentimento, garantir privacidade, perguntar onde dói mais e preparar mãos/posição. Se há instabilidade, priorizar suporte."}, {"question": "Como sua mão deve entrar em contato e por onde começa?", "answer": "Contato amplo, gradual e suave, em área menos dolorosa. Observe rosto e respiração; aumente a pressão somente quando necessário e tolerado."}, {"question": "O paciente contrai a parede antes de você tocar. O que muda na técnica?", "answer": "Reexplique, aqueça as mãos, ajuste apoios e convide à expiração tranquila. Não force. Descreva se a resistência cede ou permanece."}, {"question": "Você já obteve um sinal peritoneal claro. Qual é a melhor próxima ação?", "answer": "Parar a provocação repetida, integrar o achado, aliviar sofrimento e prosseguir com assistência/investigação indicada. Para ensino, discuta o caso ou use simulador."}, {"question": "Qual feedback você deve pedir a um preceptor?", "answer": "Se o toque foi delicado, a localização correta, a comunicação clara e a conclusão proporcional aos achados. Um roteiro digital não verifica essas habilidades motoras."}], "pitfall": "Confundir força, rapidez ou quantidade de manobras com competência.", "nextAction": "Escolha uma técnica e descreva seu passo a passo em voz alta; depois demonstre em simulador ou ambiente supervisionado."}, {"id": "t02", "name": "Tutor de Localização e Mecanismo", "role": "Roteiro educativo de raciocínio topográfico", "goal": "Ligar a história e o exame a mecanismos e hipóteses sem concluir por um sinal isolado.", "steps": [{"question": "Como resumir uma dor abdominal em uma frase útil?", "answer": "Combine início, evolução, topografia, sintomas associados, contexto de risco e estado atual. Separe dados observados de interpretação."}, {"question": "Dor periumbilical que migra para a direita sugere qual mudança de mecanismo?", "answer": "Pode representar dor visceral seguida de irritação parietal localizada. Apendicite é uma hipótese; o padrão não confirma etiologia sozinho."}, {"question": "Dor intensa com palpação pouco expressiva faz você abandonar a suspeita orgânica?", "answer": "Não. Considere isquemia, apresentações iniciais, causas retroperitoneais e modificação dos sinais por idade, sedação ou imunossupressão."}, {"question": "Uma dor epigástrica deve limitar o exame ao tubo digestivo?", "answer": "Não. Considere coração, aorta, pulmão/pleura, parede e causas metabólicas conforme apresentação e fatores de risco."}, {"question": "Como escolher o próximo exame complementar?", "answer": "Diga qual pergunta precisa responder e como o resultado mudará a conduta. Escolha método e urgência compatíveis com estabilidade, população e hipótese."}], "pitfall": "Transformar quadrante em diagnóstico e ignorar uma hipótese alternativa perigosa.", "nextAction": "Resolva um caso, formulando uma hipótese principal, uma alternativa perigosa e um dado que ajude a separá-las."}, {"id": "t03", "name": "Tutor de Epônimos e Limites", "role": "Roteiro educativo de sinais clássicos", "goal": "Aprender o nome junto da técnica, do mecanismo e do que ele não consegue provar.", "steps": [{"question": "Quais quatro elementos tornam um epônimo clinicamente útil?", "answer": "Local e técnica corretos, resposta observada, mecanismo provável e limite diagnóstico. A biografia do nomeador é contexto histórico, não prova de acurácia."}, {"question": "Como diferenciar Murphy de sensibilidade simples à direita?", "answer": "Murphy clínico clássico envolve interrupção da inspiração por dor no contato subcostal dirigido. Dor local sem essa resposta deve ser descrita como tal."}, {"question": "Qual é o erro de usar Jobert negativo para excluir perfuração?", "answer": "Gás livre pode não produzir a mudança esperada de percussão, e há apresentações variadas. A síndrome clínica e a investigação têm prioridade."}, {"question": "O que Giordano e a posição antálgica pancreática têm em comum como limites?", "answer": "São pistas inespecíficas. O primeiro localiza sensibilidade costovertebral; a segunda descreve alívio postural. Nenhum define etiologia isoladamente."}, {"question": "Todo sinal com nome próprio foi descoberto exclusivamente por quem lhe deu nome?", "answer": "Não. Atribuições históricas podem ser compartilhadas, retrospectivas ou contestadas. Prefira 'associado a' quando a autoria não estiver documentada por fonte adequada."}], "pitfall": "Colecionar nomes sem saber reproduzir a técnica, distinguir falsos positivos ou explicar o próximo passo.", "nextAction": "Selecione três sinais do catálogo e explique: como faço, o que vejo, o que sugere e o que não exclui."}, {"id": "t04", "name": "Preceptor de OSCE Abdominal", "role": "Estação educativa estruturada de exame clínico", "goal": "Praticar uma apresentação organizada para avaliação observada. OSCE significa Exame Clínico Objetivo Estruturado.", "steps": [{"question": "A estação começa: quais são suas primeiras frases?", "answer": "Apresentação, confirmação da finalidade, explicação breve, consentimento e pergunta sobre o local da dor. Verbalize que avaliaria estabilidade antes de seguir."}, {"question": "Como você demonstra o núcleo do exame sem perder a ordem?", "answer": "Posicione e exponha adequadamente; inspecione; ausculte; percuta; palpe de modo superficial e depois dirigido, começando longe da dor. Adapte a sequência ao cenário."}, {"question": "O avaliador informa dor intensa e defesa involuntária. O que você verbaliza?", "answer": "Eu interromperia manobras repetidamente dolorosas, reavaliaria estabilidade, providenciaria analgesia e solicitaria assistência/investigação urgente conforme a hipótese."}, {"question": "Como apresentar os achados em 30 segundos?", "answer": "Estado geral e sinais vitais; cronologia e topografia; achados positivos e negativos pertinentes; hipótese sindrômica; diferencial perigoso; próxima ação e reavaliação."}, {"question": "O que conta como fechamento da estação?", "answer": "Agradecer, cobrir e reposicionar a pessoa, esclarecer próximos passos, higienizar as mãos e solicitar feedback. Não prometer diagnóstico com base no desempenho do roteiro."}], "pitfall": "Recitar uma lista completa sem observar o paciente ou responder à pergunta clínica.", "nextAction": "Use o checklist em uma simulação curta e peça a um preceptor que escolha uma correção técnica prioritária."}]}, "signs": [{"id": "murphy", "name": "Sinal de Murphy", "aliases": ["Murphy clínico"], "category": "Hepatobiliar", "priority": "essencial", "anatomy": "Vesícula biliar e peritônio adjacente, no hipocôndrio direito, junto à borda lateral do reto abdominal.", "position": "Decúbito dorsal, abdome relaxado; examinador à direita.", "steps": ["Explique a manobra, identifique o local da dor e observe a respiração antes de tocar.", "Durante a expiração, acomode delicadamente as polpas digitais abaixo do rebordo costal direito, sem penetrar à força.", "Solicite uma inspiração lenta e observe simultaneamente a face e o movimento inspiratório.", "Interrompa ao surgir dor; quando necessário e tolerado, compare com o lado esquerdo sem repetir provocações."], "positive": "Dor localizada acompanhada de interrupção inspiratória súbita provocada pelo contato com a região vesicular.", "mechanism": "A inspiração desloca o fígado e a vesícula para baixo; o contato com tecidos inflamados interrompe o esforço respiratório.", "interpretation": "Favorece colecistite no contexto apropriado; combine com história, inflamação sistêmica e ultrassonografia.", "limits": "Negatividade não exclui colecistite, especialmente em apresentações atípicas. Dor isolada no quadrante não equivale ao sinal completo.", "pitfall": "Confundir o Murphy clínico com o ultrassonográfico, que localiza a dor pela pressão do transdutor sobre a vesícula visualizada.", "avoid": "Não aprofundar pressão contra resistência involuntária nem reter analgesia para preservar o sinal.", "history": {"person": "John Benjamin Murphy", "period": "Descrição de 1903", "note": "Cirurgião; a descrição original incluía técnica em gancho. O epônimo não demonstra prioridade absoluta de descoberta."}, "recall": {"question": "O que diferencia Murphy de simples dor à palpação?", "answer": "A interrupção inspiratória dolorosa provocada no local vesicular."}, "sources": ["exame-abdominal", "palpacao-historia-1"]}, {"id": "blumberg", "name": "Sinal de Blumberg", "aliases": ["dor à descompressão", "Blumberg–Shchetkin"], "category": "Irritação peritoneal", "priority": "essencial", "anatomy": "Peritônio parietal; pode ser pesquisado em diferentes regiões, não apenas na fossa ilíaca direita.", "position": "Decúbito dorsal, joelhos apoiados se isso relaxar a parede.", "steps": ["Observe imobilidade, dor com tosse e defesa antes de escolher qualquer manobra provocativa.", "Se ainda necessário, avise que fará uma única compressão suave e progressiva em região escolhida, começando longe da dor máxima.", "Retire a mão de modo rápido e controlado, sem golpear a parede.", "Pergunte se doeu mais durante a pressão ou ao soltá-la e registre localização e reação."], "positive": "Dor mais intensa à retirada da pressão do que durante a compressão.", "mechanism": "A liberação mobiliza tecidos e distende o peritônio inflamado; a dor somática tende a ser bem localizada.", "interpretation": "Sugere irritação peritoneal. Em fossa ilíaca direita pode acompanhar apendicite, mas também outras doenças.", "limits": "Ausência não exclui abdome agudo. Defesa voluntária, dor da parede e dificuldade de comunicação alteram a interpretação.", "pitfall": "Transformar qualquer dor abdominal em 'Blumberg positivo' ou registrar o epônimo sem descrever a região.", "avoid": "Se peritonismo já for evidente, dispense o teste. Não repetir descompressões dolorosas para demonstração ou confirmação por vários examinadores.", "history": {"person": "Jacob Moritz Blumberg; Dmitri Shchetkin", "period": "Publicações no início do século XX", "note": "A literatura histórica registra descrições e uso anteriores à publicação de Blumberg; prioridade disputada."}, "recall": {"question": "Blumberg identifica uma doença específica?", "answer": "Não. Identifica uma resposta compatível com irritação peritoneal."}, "sources": ["palpacao-historia-2", "exame-abdominal"]}, {"id": "rovsing", "name": "Sinal de Rovsing", "aliases": ["dor referida à fossa ilíaca direita"], "category": "Apendicular", "priority": "essencial", "anatomy": "Parede abdominal e estruturas peritoneais; estímulo à esquerda com dor percebida à direita.", "position": "Decúbito dorsal, abdome relaxado.", "steps": ["Pergunte onde a dor está antes da manobra e peça que aponte com um dedo.", "Aplique pressão leve, progressiva e tolerável na fossa ilíaca esquerda.", "Pergunte especificamente se surgiu dor à direita, mantendo a distinção entre local pressionado e local da resposta.", "Solte suavemente e descreva o método empregado; a variante moderna não exige compressão profunda ou descompressão brusca."], "positive": "Reprodução de dor na fossa ilíaca direita durante pressão no quadrante inferior esquerdo.", "mechanism": "A transmissão de tensão e mobilização das estruturas pode estimular a região inflamada; a explicação clássica exclusivamente por gás não é definitiva.", "interpretation": "Acrescenta evidência a favor de apendicite quando coerente com a história e os demais achados.", "limits": "Sensibilidade limitada e variação importante de técnica; um resultado negativo não afasta apendicite.", "pitfall": "Chamar dor somente à esquerda de Rovsing ou confundir a resposta com descompressão contralateral.", "avoid": "Não reproduzir manobras históricas vigorosas de compressão do cólon. Pare com dor relevante ou defesa evidente.", "history": {"person": "Niels Thorkild Rovsing", "period": "1907", "note": "Cirurgião dinamarquês. Sua técnica original difere da pressão simples hoje usual; documentar a técnica melhora a comunicação."}, "recall": {"question": "No Rovsing moderno, onde se pressiona e onde aparece a dor?", "answer": "Pressiona-se à esquerda; a resposta de interesse aparece na fossa ilíaca direita."}, "sources": ["palpacao-historia-1", "exame-abdominal"]}, {"id": "psoas", "name": "Sinal do psoas", "aliases": ["teste de extensão do psoas", "Cope — psoas"], "category": "Apendicular", "priority": "essencial", "anatomy": "Iliopsoas direito e estruturas retrocecais ou retroperitoneais adjacentes.", "position": "Decúbito lateral esquerdo para testar o lado direito; variante ativa em decúbito dorsal.", "steps": ["Verifique limitações dolorosas do quadril e explique que o movimento deve permanecer confortável.", "Na técnica passiva, estabilize a pelve e leve delicadamente a coxa direita para extensão, sem arquear a coluna.", "Observe se aparece dor abdominal ou no flanco; diferencie-a de dor articular ou lombar habitual.", "Na variante ativa, peça flexão suave do quadril contra resistência leve e registre que foi esta a técnica utilizada."], "positive": "Dor abdominal ou retroperitoneal reproduzida ao alongar ou contrair o iliopsoas.", "mechanism": "Alongamento ou contração mobiliza o músculo junto de um foco inflamatório; apêndice retrocecal é uma possibilidade.", "interpretation": "Pode ocorrer na apendicite retrocecal, abscesso do psoas e outros processos retroperitoneais.", "limits": "Muitos pacientes com apendicite têm resultado negativo; posição do apêndice e estágio da doença modificam a resposta.", "pitfall": "Considerar toda dor ao mover o quadril como apendicite ou apresentar as variantes ativa e passiva como técnicas idênticas.", "avoid": "Não forçar amplitude em prótese, trauma, artropatia, dor intensa ou peritonite já estabelecida.", "history": {"person": "Vincent Zachary Cope", "period": "Descrição difundida em 1921", "note": "Cirurgião britânico. Há outras atribuições históricas para variantes; o nome anatômico é mais inequívoco."}, "recall": {"question": "Por que psoas negativo não exclui apendicite?", "answer": "O apêndice inflamado pode não estar em contato com o músculo."}, "sources": ["movimento-historia", "dor-aguda-exame"]}, {"id": "obturador", "name": "Sinal do obturador", "aliases": ["Cope — obturador", "teste de rotação da coxa"], "category": "Apendicular", "priority": "essencial", "anatomy": "Obturador interno, parede lateral da pelve e vísceras pélvicas adjacentes.", "position": "Decúbito dorsal, quadril e joelho direitos flexionados aproximadamente a 90°, conforme tolerância.", "steps": ["Apoie o joelho e o tornozelo direitos sem comprimir o abdome.", "Mantenha a coxa flexionada e leve suavemente o tornozelo para fora, produzindo rotação interna do quadril.", "Observe se a manobra reproduz dor no hipogástrio ou no quadrante inferior direito.", "Retorne à posição neutra e diferencie dor abdominal de dor na articulação ou na musculatura."], "positive": "Dor hipogástrica ou abdominal reproduzida pela rotação interna do quadril flexionado.", "mechanism": "A rotação alonga o obturador interno; inflamação pélvica contígua pode tornar esse movimento doloroso.", "interpretation": "Pode apoiar suspeita de apêndice pélvico ou outro processo inflamatório/coleção na pelve.", "limits": "Baixa sensibilidade; a ausência do sinal não exclui apendicite pélvica. Não diferencia sozinho causas intestinais, ginecológicas ou musculoesqueléticas.", "pitfall": "Mover o tornozelo para dentro e chamar o movimento de rotação interna; com o quadril flexionado ocorre o contrário.", "avoid": "Não forçar quadril doloroso, pós-operatório ortopédico ou paciente incapaz de colaborar; não insistir quando já há indicação de avaliação urgente.", "history": {"person": "Vincent Zachary Cope", "period": "1919", "note": "A descrição histórica incluía rotação da coxa; o ensino atual costuma enfatizar a rotação interna."}, "recall": {"question": "Como produzir rotação interna com quadril e joelho flexionados?", "answer": "Manter o joelho apoiado e deslocar o tornozelo para fora."}, "sources": ["movimento-historia", "exame-abdominal"]}, {"id": "mcburney", "name": "Ponto de McBurney", "aliases": ["dor no ponto de McBurney"], "category": "Apendicular", "priority": "essencial", "anatomy": "Junção do terço lateral com os dois terços mediais da linha entre a espinha ilíaca anterossuperior direita e o umbigo.", "position": "Decúbito dorsal, paciente confortável e examinador à direita.", "steps": ["Identifique o umbigo e a espinha ilíaca anterossuperior direita sobre a anatomia real.", "Imagine a linha entre esses marcos e localize o ponto a um terço do trajeto a partir da espinha ilíaca.", "Comece a palpação longe da área mais dolorosa e aproxime-se com pressão superficial progressiva.", "Registre se existe dor focal, defesa ou massa e descreva eventual dor fora do ponto clássico."], "positive": "Dor localizada à palpação dessa região, interpretada no conjunto do exame.", "mechanism": "Inflamação apendicular próxima ao peritônio parietal pode produzir dor somática bem localizada.", "interpretation": "É um marco de orientação para suspeita de apendicite; não representa a localização obrigatória da ponta do apêndice.", "limits": "Apêndice retrocecal, pélvico, gestação e variações anatômicas deslocam a apresentação. Idosos e imunossuprimidos podem ter achados discretos.", "pitfall": "Medir um terço a partir do umbigo ou excluir apendicite porque a dor não coincide milimetricamente com o marco.", "avoid": "Não tentar palpar o apêndice normal nem pressionar repetidamente uma área com defesa involuntária.", "history": {"person": "Charles McBurney", "period": "Final do século XIX", "note": "Cirurgião norte-americano associado à descrição clínica e à abordagem cirúrgica; ponto e incisão são conceitos diferentes."}, "recall": {"question": "Um terço contado a partir de qual marco?", "answer": "Da espinha ilíaca anterossuperior direita em direção ao umbigo."}, "sources": ["exame-abdominal", "atraso-apendicite"]}, {"id": "lanz", "name": "Ponto de Lanz", "aliases": ["sensibilidade no ponto de Lanz"], "category": "Apendicular", "priority": "complementar", "anatomy": "Junção do terço direito com os dois terços esquerdos da linha que une as duas espinhas ilíacas anterossuperiores.", "position": "Decúbito dorsal, membros inferiores apoiados e parede relaxada.", "steps": ["Localize as duas espinhas ilíacas anterossuperiores, sem usar o umbigo como referência para esta linha.", "Divida mentalmente o trajeto transversal em três partes e encontre a junção mais próxima do lado direito.", "Palpe a região com polpas digitais, começando com pressão leve.", "Relacione a sensibilidade ao restante do quadrante inferior direito e registre qualquer variação topográfica."], "positive": "Dor focal na região do ponto durante a palpação.", "mechanism": "É uma projeção superficial de orientação para a região apendicular, variável entre pessoas.", "interpretation": "Complementa o mapeamento da dor quando há suspeita de apendicite; ajuda a ensinar anatomia de superfície.", "limits": "Não é um teste confirmatório nem um substituto da avaliação de todo o abdome. Acurácia isolada e reprodutibilidade não justificam decisões automáticas.", "pitfall": "Confundir sua linha entre as espinhas ilíacas com a linha espinha–umbigo utilizada para McBurney.", "avoid": "Não multiplicar palpação dolorosa só para pesquisar dois pontos próximos. Na presença de peritonismo, priorize a decisão clínica.", "history": {"person": "Otto Lanz", "period": "Final do século XIX e início do XX", "note": "Cirurgião suíço. A data exata da descrição inicial não foi confirmada na fonte consultada."}, "recall": {"question": "Qual referência distingue Lanz de McBurney?", "answer": "Lanz usa as duas espinhas ilíacas; McBurney usa espinha ilíaca direita e umbigo."}, "sources": ["lanz-dicionario", "atraso-apendicite"]}, {"id": "dunphy", "name": "Dor à tosse — sinal de Dunphy", "aliases": ["teste da tosse"], "category": "Irritação peritoneal", "priority": "essencial", "anatomy": "Parede abdominal, diafragma e peritônio mobilizados pelo esforço da tosse.", "position": "Posição confortável; não é necessário obrigar o paciente a levantar.", "steps": ["Antes de palpar, pergunte se tossir, caminhar ou mudar de posição piora a dor.", "Se a resposta ainda for necessária e o paciente tolerar, peça uma tosse leve, uma única vez.", "Observe expressão facial, proteção involuntária do abdome e localização apontada pelo paciente.", "Registre dor localizada ou difusa e aproveite o resultado para limitar manobras mais dolorosas."], "positive": "Dor abdominal provocada ou intensificada pela tosse; na suspeita de apendicite interessa a localização no quadrante inferior direito.", "mechanism": "A tosse contrai a parede e mobiliza estruturas abdominais, podendo provocar dor quando há inflamação peritoneal.", "interpretation": "Pode ser uma forma inicial menos invasiva de buscar peritonismo; também ocorre em dor da parede.", "limits": "Não diagnostica apendicite sozinho e não exclui gravidade quando negativo. Tosse espontânea já observada pode fornecer a informação.", "pitfall": "Tomar qualquer desconforto respiratório como dor peritoneal ou exigir tosse vigorosa para 'validar' a resposta.", "avoid": "Dispense a provocação se houver dor intensa evidente, dificuldade respiratória ou restrição pós-operatória; não repetir por demonstração.", "history": {"person": "Atribuição histórica a Dunphy; identidade/prioridade não fixadas aqui", "period": "Descrição disseminada no século XX", "note": "A associação do sobrenome varia nas referências; o teste da tosse tem descrições anteriores ao epônimo."}, "recall": {"question": "Por que observar a tosse antes de descomprimir o abdome?", "answer": "Ela pode demonstrar dor ao movimento e evitar uma provocação dolorosa desnecessária."}, "sources": ["apendicite-ncbi", "atraso-apendicite"]}, {"id": "markle", "name": "Sinal de Markle", "aliases": ["teste da queda sobre os calcanhares", "heel-drop test"], "category": "Irritação peritoneal", "priority": "complementar", "anatomy": "Transmissão de pequeno impacto dos pés para as estruturas peritoneais.", "position": "Em pé somente se o paciente estiver estável, seguro e capaz de sustentar o próprio peso.", "steps": ["Avalie equilíbrio, força, dor e risco de queda; explique que a manobra é opcional.", "Com apoio próximo e supervisão, peça para elevar os calcanhares ficando brevemente nas pontas dos pés.", "Solicite que retorne os calcanhares ao chão, sem salto e sem força imposta pelo examinador.", "Registre se isso reproduz dor abdominal e encerre após uma tentativa; a observação de dor ao caminhar pode ser suficiente."], "positive": "Dor abdominal desencadeada pelo pequeno impacto da descida dos calcanhares.", "mechanism": "O movimento transmite aceleração às estruturas abdominais e pode tornar perceptível inflamação peritoneal.", "interpretation": "Pode apoiar suspeita de apendicite/peritonismo em pacientes selecionados. Estudo prospectivo encontrou utilidade como parte de avaliação combinada.", "limits": "Negatividade não exclui apendicite; não é requisito obrigatório para diagnosticar abdome agudo.", "pitfall": "Transformar o teste em salto ou exigir que um paciente debilitado fique em pé.", "avoid": "Não executar em instabilidade, fragilidade, risco de queda, trauma, limitação dos membros ou peritonite evidente.", "history": {"person": "George Bushar Markle IV", "period": "Década de 1970", "note": "Epônimo associado ao teste de impacto dos calcanhares; manter o nome descritivo favorece clareza."}, "recall": {"question": "Qual é o primeiro requisito do teste?", "answer": "Segurança para ficar em pé; sem isso, o teste deve ser dispensado."}, "sources": ["markle-estudo"]}, {"id": "giordano", "name": "Sinal de Giordano", "aliases": ["dor à punho-percussão lombar", "sensibilidade costovertebral"], "category": "Renal e retroperitoneal", "priority": "essencial", "anatomy": "Ângulo costovertebral e loja renal; estruturas musculoesqueléticas locais também podem doer.", "position": "Sentado, ou posição alternativa confortável que permita examinar as regiões lombares.", "steps": ["Pergunte o lado doloroso e inspecione pele, trauma e limitações locais.", "Comece pelo lado sem dor; apoie uma mão espalmada na região costovertebral.", "Com a borda ulnar do outro punho, aplique um toque suave sobre a mão de apoio, nunca um golpe forte.", "Compare os lados e registre a resposta localizada; pare assim que a informação estiver obtida."], "positive": "Dor desproporcional ou reprodução da dor habitual com a percussão suave da região costovertebral.", "mechanism": "O impacto transmite movimento a tecidos da loja renal e estruturas próximas, tornando dolorosa uma região inflamada.", "interpretation": "Pode acompanhar pielonefrite e litíase, mas precisa ser relacionado a febre, sintomas urinários e exames apropriados.", "limits": "É inespecífico e pode ser positivo em causas musculares ou vertebrais; negativo não afasta obstrução ou infecção.", "pitfall": "Concluir 'cálculo renal confirmado' apenas pelo sinal, ou confundir a manobra com palpação renal de Israel.", "avoid": "Não golpear diretamente com força nem provocar repetidamente; em trauma, dor intensa ou instabilidade, restrinja-se ao necessário.", "history": {"person": "Davide Giordano — atribuição tradicional", "period": "Transição dos séculos XIX–XX; data inicial não confirmada", "note": "O termo descritivo sensibilidade costovertebral comunica o achado sem depender da autoria."}, "recall": {"question": "Giordano positivo diferencia cálculo de pielonefrite?", "answer": "Não. A interpretação depende do quadro clínico e da investigação."}, "sources": ["ufcspa-manual", "pielonefrite-estudo"]}, {"id": "israel", "name": "Manobra de Israel", "aliases": ["palpação renal em decúbito lateral", "método de Israel"], "category": "Renal e retroperitoneal", "priority": "complementar", "anatomy": "Rim superior no decúbito lateral, acessado por palpação bimanual da região lombar e do abdome.", "position": "Deitado sobre o lado oposto ao rim examinado; para o rim direito, decúbito lateral esquerdo.", "steps": ["Explique a posição e apoie cabeça e membros de modo confortável, com discreta flexão das pernas se tolerada.", "Coloque uma mão na região lombar do rim examinado para oferecer apoio posterior.", "Acomode a outra mão anteriormente, avançando de maneira delicada em direção à região subcostal correspondente.", "Durante uma inspiração lenta, procure perceber a descida do polo renal; relaxe a pressão na expiração e descreva o achado."], "positive": "Não é um teste binário: registre rim ou massa palpável, contorno, mobilidade e sensibilidade.", "mechanism": "O decúbito e a inspiração podem aproximar o rim das mãos e facilitar seu reconhecimento.", "interpretation": "Pode ajudar a identificar rim aumentado, baixo ou massa na região renal, que requer caracterização por imagem.", "limits": "O rim frequentemente não é palpável; rim direito palpável em pessoa magra pode ser normal. Palpação não mede função renal.", "pitfall": "Confundir Israel com Giordano ou atribuir toda massa do flanco ao rim.", "avoid": "Não comprimir intensamente massa dolorosa ou pulsátil; não insistir em trauma, defesa ou mal-estar.", "history": {"person": "James Adolf Israel", "period": "1848–1926; data da manobra não confirmada", "note": "Cirurgião e urologista. A definição institucional consultada confirma o decúbito contralateral e a palpação bimanual."}, "recall": {"question": "Em qual lado deitar para examinar o rim direito por Israel?", "answer": "No lado esquerdo, deixando o rim direito por cima."}, "sources": ["israel-cun"]}, {"id": "guyon", "name": "Palpação bimanual renal de Guyon", "aliases": ["método de Guyon", "baloteio renal — variante"], "category": "Renal e retroperitoneal", "priority": "complementar", "anatomy": "Rim situado entre a mão lombar posterior e a mão abdominal anterior.", "position": "Decúbito dorsal, relaxamento abdominal e joelhos apoiados conforme conforto.", "steps": ["Posicione uma mão sob a região lombar do lado examinado, abaixo da última costela.", "Coloque a outra no abdome, lateralmente ao reto e abaixo do rebordo costal correspondente.", "Durante inspiração lenta, aproxime as mãos suavemente para tentar perceber o polo renal.", "Se necessário, descreva o contato entre as mãos sem lançar ou golpear o órgão; registre lado, volume aparente, mobilidade e dor."], "positive": "Achado descritivo: percepção de um polo renal ou massa entre as mãos, com características a documentar.", "mechanism": "A mão posterior aproxima a loja renal da mão anterior; a respiração favorece a descida do rim.", "interpretation": "Auxilia a topografia de massas e organomegalias, mas não estabelece a natureza benigna ou maligna.", "limits": "Obesidade, musculatura e profundidade retroperitoneal limitam o exame; não palpar o rim é frequente na normalidade.", "pitfall": "Confundir a técnica renal com o canal de Guyon no punho ou usar baloteio vigoroso como etapa obrigatória.", "avoid": "Não insistir em massa pulsátil, trauma ou dor acentuada; ultrassonografia esclarece dúvidas com menos desconforto.", "history": {"person": "Jean Casimir Félix Guyon", "period": "1831–1920", "note": "Cirurgião/urologista. A técnica dorsal é distinguida da variante lateral de Israel; a data original não foi confirmada."}, "recall": {"question": "Qual diferença postural prática entre Guyon e Israel?", "answer": "Guyon: dorsal; Israel: lateral, sobre o lado oposto ao rim examinado."}, "sources": ["israel-cun", "guyon-historia", "clinmethods-exame"]}, {"id": "jobert", "name": "Sinal de Jobert", "aliases": ["desaparecimento da macicez hepática"], "category": "Percussão e perfuração", "priority": "essencial", "anatomy": "Área hepática normalmente maciça à percussão; gás interposto pode substituir esse som por timpanismo.", "position": "Decúbito dorsal, com acesso ao hipocôndrio direito.", "steps": ["Percuta suavemente a área hepática esperada e compare com as regiões pulmonar e abdominal adjacentes.", "Verifique se existe transição para a macicez habitual ou se persiste som timpânico na região pré-hepática.", "Relacione o achado a dor súbita, defesa, distensão, procedimentos recentes e estabilidade circulatória.", "Registre 'macicez hepática não identificada' com a técnica utilizada e procure confirmação por imagem quando indicada."], "positive": "Timpanismo ou perda da macicez sobre a projeção do fígado.", "mechanism": "A presença de gás entre a parede e o fígado altera a transmissão sonora; pode haver ar livre ou alça intestinal interposta.", "interpretation": "Em quadro compatível, levanta suspeita de pneumoperitônio por perfuração de víscera oca e exige avaliação urgente.", "limits": "Não confirma perfuração; interposição colônica, distensão e limitações técnicas podem produzir achados semelhantes. Ausência não exclui perfuração.", "pitfall": "Usar Jobert como sinônimo de pneumoperitônio confirmado ou ignorar o diferencial de Chilaiditi.", "avoid": "Não prolongar percussão em paciente instável ou com peritonismo; o achado não deve atrasar avaliação cirúrgica.", "history": {"person": "Antoine-Joseph Jobert de Lamballe — atribuição tradicional", "period": "Século XIX; prioridade não confirmada", "note": "A nomenclatura é mantida pelo uso didático; a descrição objetiva do som é mais informativa."}, "recall": {"question": "Perda de macicez hepática prova perfuração?", "answer": "Não. É uma pista que exige contexto e diferenciação de gás em alça interposta."}, "sources": ["unila-manual", "chilaiditi"]}, {"id": "courvoisier", "name": "Sinal de Courvoisier–Terrier", "aliases": ["Courvoisier", "vesícula palpável com icterícia"], "category": "Hepatobiliar", "priority": "essencial", "anatomy": "Vesícula distendida, palpável abaixo do rebordo costal direito, em paciente ictérico.", "position": "Decúbito dorsal, palpação abdominal cuidadosa e progressiva.", "steps": ["Procure icterícia em iluminação adequada e investigue evolução, colúria e acolia fecal.", "Palpe com delicadeza a região subcostal direita durante a inspiração, distinguindo borda hepática de estrutura vesicular.", "Descreva uma eventual massa lisa, distendida e pouco dolorosa, sem pressioná-la repetidamente.", "Correlacione a associação com exames de colestase e imagem das vias biliares."], "positive": "Associação clássica entre icterícia e vesícula palpável distendida, geralmente pouco dolorosa.", "mechanism": "Obstrução distal com vesícula ainda distensível pode aumentar seu volume; inflamação crônica e fibrose modificam essa resposta.", "interpretation": "Favorece investigação de obstrução biliar, inclusive neoplasia pancreática/periampular; não equivale a diagnóstico de câncer.", "limits": "Há obstruções benignas com vesícula palpável e tumores sem esse achado. É um sinal probabilístico, não uma lei.", "pitfall": "Declarar malignidade ou excluir cálculo com base apenas na palpação; confundir vesícula com hepatomegalia.", "avoid": "Não fazer palpação profunda repetida sobre massa dolorosa ou pulsátil; não adiar investigação por ausência do sinal.", "history": {"person": "Ludwig Georg Courvoisier; associação tradicional a Félix Terrier", "period": "Courvoisier: 1890", "note": "A história consultada sustenta a descrição de Courvoisier; a prioridade específica de Terrier não foi confirmada."}, "recall": {"question": "Por que dizer 'sinal' e não 'lei' de Courvoisier?", "answer": "Porque existem exceções benignas e malignas, e o achado não determina a causa."}, "sources": ["palpacao-historia-1", "courvoisier-caso"]}, {"id": "macicez-movel", "name": "Macicez móvel", "aliases": ["macicez móvel de decúbito", "shifting dullness"], "category": "Ascite", "priority": "essencial", "anatomy": "Líquido livre peritoneal em regiões dependentes e alças com gás em posição mais alta.", "position": "Comece em decúbito dorsal e repita em decúbito lateral tolerado.", "steps": ["Percuta do centro abdominal em direção a um flanco e identifique a mudança de timpanismo para macicez.", "Marque mentalmente a fronteira e peça ajuda para o paciente virar de lado, sem risco de queda.", "Aguarde breve acomodação do líquido e percuta novamente a mesma região e o novo lado dependente.", "Registre se a fronteira se deslocou com a posição, mantendo pressão e intensidade de percussão semelhantes."], "positive": "A região antes maciça torna-se mais timpânica ao ficar por cima, com macicez deslocando-se para a região dependente.", "mechanism": "Líquido livre se redistribui por gravidade; o gás intestinal ocupa a posição superior.", "interpretation": "Aumenta a probabilidade de ascite livre, especialmente quando associado a outros achados.", "limits": "Pouco líquido, loculações, obesidade, massas e gás dificultam o teste. Negativo não exclui ascite; não existe volume exato universal detectável.", "pitfall": "Dizer que o som mudou sem comparar a mesma área ou atribuir toda distensão abdominal a líquido.", "avoid": "Não girar paciente instável ou com dor intensa. Não escolher local de punção só pela percussão; usar ultrassonografia quando disponível.", "history": {"person": "Manobra descritiva, sem autor único estabelecido", "period": "Propedêutica clássica", "note": "A física do deslocamento importa mais que memorizar um epônimo."}, "recall": {"question": "O que torna esta manobra 'móvel'?", "answer": "A fronteira da macicez muda com o decúbito."}, "sources": ["stanford-ascite-benchmarks", "ascite-preditivo"]}, {"id": "piparote", "name": "Onda líquida ou piparote", "aliases": ["sinal da onda ascítica", "fluid wave"], "category": "Ascite", "priority": "complementar", "anatomy": "Transmissão de impulso entre flancos através de líquido; a parede também pode transmitir falsas ondas.", "position": "Decúbito dorsal, abdome exposto com privacidade preservada.", "steps": ["Peça ao paciente ou assistente que coloque a borda ulnar de uma mão na linha média, com pressão suficiente para amortecer a parede.", "Apoie uma de suas mãos em um flanco como receptora.", "Com a outra, produza um toque leve no flanco oposto, sem golpear o abdome.", "Procure sentir um impulso na mão receptora e repita apenas se a primeira tentativa ficou tecnicamente duvidosa."], "positive": "Impulso perceptível no flanco oposto apesar do amortecimento da parede na linha média.", "mechanism": "O líquido pode transmitir a onda mecânica através da cavidade; o bloqueio mediano busca reduzir condução superficial.", "interpretation": "Pode apoiar ascite de maior volume, mas deve ser combinado com história, macicez móvel e imagem.", "limits": "Obesidade e transmissão pela pele produzem falsos positivos; resultados dependem de técnica e volume.", "pitfall": "Omitir a mão na linha média e interpretar qualquer tremor da parede como onda líquida.", "avoid": "Evitar impactos vigorosos, repetição desnecessária ou pressão em abdome doloroso; não usar o teste para estimar litros com precisão.", "history": {"person": "Sem atribuição individual segura", "period": "Propedêutica clássica", "note": "O nome descreve o gesto; não representa uma síndrome específica ou causa determinada de ascite."}, "recall": {"question": "Para que serve a mão na linha média?", "answer": "Amortecer a transmissão superficial pela parede abdominal."}, "sources": ["ufcspa-manual", "ascite-pocus"]}, {"id": "skoda", "name": "Semicírculo de Skoda", "aliases": ["mapa percussório da ascite"], "category": "Ascite", "priority": "complementar", "anatomy": "Timpanismo central e macicez nas regiões inferiores/laterais do abdome com líquido livre.", "position": "Decúbito dorsal, abdome relaxado.", "steps": ["Inicie a percussão suave em área central timpânica e avance em trajetos radiais para flancos e hipogástrio.", "Identifique e marque as transições de som em diferentes trajetos, evitando deduzir um contorno a partir de um único ponto.", "Una mentalmente as fronteiras: na descrição clássica da ascite, a macicez periférica/inferior delimita concavidade voltada superiormente.", "Complete, quando tolerado, com macicez móvel para verificar redistribuição gravitacional."], "positive": "Distribuição percussória compatível com líquido periférico e alças mais centrais; não basta qualquer desenho semicircular.", "mechanism": "A gravidade desloca líquido e alças de densidades diferentes, criando uma fronteira acústica aproximada.", "interpretation": "Ajuda a visualizar a distribuição de ascite; massa pélvica, bexiga cheia e grandes cistos podem produzir macicez central diferente.", "limits": "Forma corporal, volume, loculação e gás alteram o desenho. O semicírculo isolado não confirma ascite nem sua causa.", "pitfall": "Decorar concavidade sem mapear onde está o som maciço ou chamar qualquer macicez pélvica de ascite.", "avoid": "Não usar o mapa para planejar punção sem avaliação apropriada; evitar exame prolongado em instabilidade.", "history": {"person": "Josef Škoda — atribuição tradicional", "period": "Século XIX; descrição específica não confirmada", "note": "Médico associado à propedêutica por percussão; não se afirma prioridade de descoberta."}, "recall": {"question": "O que deve ser lembrado antes da forma do semicírculo?", "answer": "Na ascite livre, o líquido tende a ficar dependente e o gás mais central/superior."}, "sources": ["unila-manual", "ufcspa-manual"]}, {"id": "castell", "name": "Sinal de Castell", "aliases": ["sinal de percussão esplênica"], "category": "Baço", "priority": "complementar", "anatomy": "Último espaço intercostal esquerdo na linha axilar anterior, próximo à projeção inferior do baço.", "position": "Decúbito dorsal, braço posicionado confortavelmente para acesso lateral.", "steps": ["Identifique a linha axilar anterior e o espaço intercostal mais inferior acessível, evitando percutir sobre a costela.", "Percuta suavemente durante a expiração e memorize o som.", "Peça uma inspiração profunda tolerada e percuta o mesmo ponto com técnica semelhante.", "Compare os sons e registre se ocorreu mudança de timpanismo/ressonância para macicez."], "positive": "A percussão antes timpânica torna-se maciça durante a inspiração.", "mechanism": "Um baço aumentado pode descer com o diafragma e ocupar a região anteriormente relacionada a estruturas com gás.", "interpretation": "Aumenta a suspeita de esplenomegalia e orienta palpação cuidadosa ou confirmação por ultrassonografia.", "limits": "Não confirma esplenomegalia; estômago, cólon, biotipo e técnica interferem. Um resultado negativo não afasta aumento discreto.", "pitfall": "Trocar de espaço entre as fases respiratórias ou classificar uma área já maciça na expiração como mudança inspiratória.", "avoid": "Não insistir em inspiração dolorosa ou percussão forte. Em trauma ou baço potencialmente frágil, evite palpação agressiva.", "history": {"person": "Donald O. Castell", "period": "1967", "note": "Descrição de técnica de percussão publicada em Annals of Internal Medicine; não confundir com a palpação esplênica."}, "recall": {"question": "Qual mudança define Castell positivo?", "answer": "Som que se torna maciço na inspiração, no mesmo ponto percutido."}, "sources": ["stanford-baco", "castell-original"]}, {"id": "traube", "name": "Percussão do espaço de Traube", "aliases": ["Traube ocupado", "área de Traube"], "category": "Baço", "priority": "complementar", "anatomy": "Área semilunar do hemitórax inferior esquerdo sobre a bolha gástrica, entre rebordo costal e estruturas adjacentes.", "position": "Decúbito dorsal; braço esquerdo confortável, permitindo acesso ao tórax inferior.", "steps": ["Identifique a área inferior esquerda do tórax e o rebordo costal sobre a topografia real do paciente.", "Percuta suavemente em sequência para reconhecer o timpanismo habitual associado ao conteúdo gasoso.", "Mapeie eventual macicez e relacione-a à inspiração e à posição.", "Integre o resultado à palpação esplênica e a possíveis causas gástricas, colônicas ou pleuropulmonares."], "positive": "Macicez em área habitualmente timpânica; o registro objetivo é preferível ao termo isolado 'ocupado'.", "mechanism": "Tecido sólido, líquido ou conteúdo digestivo substituem o predomínio acústico do gás.", "interpretation": "Pode levantar suspeita de esplenomegalia, mas também ocorrer por estômago cheio, conteúdo colônico e alterações torácicas.", "limits": "Limites e sonoridade variam. Macicez não é equivalente a baço palpável e não determina o tamanho do órgão.", "pitfall": "Considerar 'Traube ocupado' diagnóstico de esplenomegalia sem avaliar refeição recente, tórax e outros achados.", "avoid": "Não percutir com força sobre costelas dolorosas; não atrasar investigação de sangramento ou trauma por este achado complementar.", "history": {"person": "Ludwig Traube", "period": "Século XIX", "note": "Médico associado ao desenvolvimento da propedêutica; autoria exata da delimitação adotada varia entre referências."}, "recall": {"question": "Traube maciço significa obrigatoriamente baço aumentado?", "answer": "Não. Conteúdo gástrico/colônico e causas torácicas também modificam o som."}, "sources": ["stanford-baco", "clinmethods-exame"]}, {"id": "schuster", "name": "Posição de Schuster para palpação do baço", "aliases": ["Schuster", "palpação esplênica em decúbito lateral direito"], "category": "Baço", "priority": "complementar", "anatomy": "Baço no hipocôndrio esquerdo, deslocado mais anteriormente pela posição lateral.", "position": "Decúbito lateral direito ou semilateral direito, com braço esquerdo elevado de forma confortável e perna esquerda discretamente flexionada.", "steps": ["Posicione e apoie o paciente sem torcer coluna ou ombro; ajuste a inclinação ao conforto.", "Comece a palpação longe do rebordo esquerdo, inclusive inferiormente se houver suspeita de grande aumento.", "Avance apenas durante a expiração; na inspiração seguinte mantenha a mão e aguarde a borda esplênica vir ao encontro dos dedos.", "Se houver contato, descreva borda, entalhe quando perceptível, consistência, extensão e dor."], "positive": "Percepção de borda compatível com baço; a posição é uma técnica facilitadora, não um 'sinal positivo' independente.", "mechanism": "Gravidade e inspiração aproximam o órgão da parede, melhorando a chance de palpação.", "interpretation": "Complementa o exame em decúbito dorsal e pode revelar esplenomegalia não percebida inicialmente.", "limits": "Baço normal costuma não ser palpável, mas palpabilidade isolada não define etiologia. Massas renais e colônicas confundem.", "pitfall": "Começar diretamente junto ao rebordo e perder a borda de um baço muito aumentado.", "avoid": "Não 'cavar' sob as costelas nem mobilizar vigorosamente baço possivelmente frágil, como em mononucleose ou trauma.", "history": {"person": "Epônimo Schuster; atribuição biográfica não confirmada", "period": "Propedêutica clássica", "note": "As variantes de posição recebem descrições diferentes; registrar o decúbito empregado evita ambiguidade."}, "recall": {"question": "Quem deve se mover durante a inspiração: os dedos ou o baço?", "answer": "A mão espera; o movimento respiratório traz a borda em sua direção."}, "sources": ["unila-manual", "stanford-baco"]}, {"id": "carnett", "name": "Sinal de Carnett", "aliases": ["teste de contração da parede abdominal"], "category": "Parede abdominal", "priority": "essencial", "anatomy": "Músculos, nervos e demais estruturas da parede abdominal comparados às fontes viscerais de dor.", "position": "Decúbito dorsal; pequena elevação da cabeça e dos ombros apenas se tolerada.", "steps": ["Peça que o paciente indique o ponto mais doloroso com um dedo.", "Palpe esse ponto com pressão leve e registre a intensidade da dor em repouso.", "Mantendo pressão semelhante, solicite elevação suave da cabeça e dos ombros para contrair a parede.", "Compare a dor nas duas condições e encerre sem exigir esforço prolongado."], "positive": "Dor que permanece ou aumenta com a contração da musculatura abdominal.", "mechanism": "A contração torna a parede mais tensa e pode manter a dor proveniente dela; também reduz a transmissão da pressão a estruturas profundas.", "interpretation": "Favorece uma origem na parede, como aprisionamento nervoso, dor muscular ou hematoma, sobretudo em dor focal persistente.", "limits": "Não exclui doença intra-abdominal concomitante; peritonite, incapacidade de contrair e dor difusa prejudicam a interpretação.", "pitfall": "Usar Carnett positivo para encerrar investigação de dor aguda grave ou rotular a dor como psicológica.", "avoid": "Dispense o esforço em instabilidade, peritonite evidente, dor intensa, cirurgia recente com restrição ou limitação musculoesquelética.", "history": {"person": "John B. Carnett", "period": "1926", "note": "Cirurgião associado à distinção clínica entre dor da parede e visceral; não é um teste de veracidade da dor."}, "recall": {"question": "Carnett positivo prova que não existe emergência visceral?", "answer": "Não. Ele apenas favorece participação da parede no contexto adequado."}, "sources": ["carnett-estudo", "fothergill-carnett"]}, {"id": "fothergill", "name": "Sinal de Fothergill", "aliases": ["massa da parede que persiste à contração"], "category": "Parede abdominal", "priority": "complementar", "anatomy": "Massa no músculo reto abdominal ou em sua bainha.", "position": "Decúbito dorsal; contração breve e confortável da parede.", "steps": ["Observe a parede e identifique delicadamente os limites da massa com a musculatura relaxada.", "Peça pequena elevação da cabeça e dos ombros, sem fazer força contra a massa.", "Verifique se a formação continua palpável e fica relativamente fixa durante a contração.", "Registre lado, limites, sensibilidade, equimoses e contexto de anticoagulação, tosse, trauma ou cirurgia."], "positive": "Massa que permanece palpável e relativamente fixa com o reto contraído; a descrição clássica tende a respeitar a linha média.", "mechanism": "Uma lesão situada na própria parede acompanha sua contração em vez de ficar protegida por ela.", "interpretation": "Pode orientar para hematoma da bainha do reto ou outra massa da parede e ajudar a evitar confusão com lesão visceral.", "limits": "Não determina etiologia; hematomas extensos, especialmente inferiores, podem ultrapassar limites clássicos. Imagem é necessária se houver dúvida ou gravidade.", "pitfall": "Confundir Fothergill, que descreve massa, com Carnett, que compara dor.", "avoid": "Não comprimir ou massagear massa dolorosa; se houver choque, queda de hemoglobina ou progressão rápida, priorize avaliação urgente.", "history": {"person": "William Edward Fothergill", "period": "1926", "note": "Médico ginecologista. A descrição da massa não torna o sinal infalível nem exclusivo de hematoma."}, "recall": {"question": "Qual é a diferença central entre Fothergill e Carnett?", "answer": "Fothergill avalia a persistência da massa; Carnett avalia a dor com contração."}, "sources": ["fothergill-carnett", "hematoma-casos"]}, {"id": "cullen", "name": "Sinal de Cullen", "aliases": ["equimose periumbilical"], "category": "Hemorragia e inspeção", "priority": "essencial", "anatomy": "Pele e tecido subcutâneo ao redor do umbigo.", "position": "Inspeção em posição confortável, com iluminação adequada e exposição restrita à área necessária.", "steps": ["Observe umbigo e região ao redor, incluindo alterações de cor e edema.", "Pergunte sobre início, trauma, injeções, cirurgias e medicamentos que favoreçam sangramento.", "Relacione o achado com dor, sinais circulatórios, possibilidade de gestação e outras equimoses.", "Documente extensão e aspecto, sem depender de fotografia; se fotografar em assistência, respeite consentimento e privacidade."], "positive": "Equimose ou coloração hemorrágica periumbilical, com ou sem edema.", "mechanism": "Sangue de planos profundos pode alcançar o subcutâneo através de trajetos fasciais e ligamentares.", "interpretation": "Sinal de alerta para possível hemorragia abdominal/retroperitoneal; pancreatite é uma causa possível, não exclusiva.", "limits": "Pode aparecer tardiamente e estar ausente em hemorragia grave. Trauma local e doenças da parede também produzem equimoses.", "pitfall": "Diagnosticar pancreatite hemorrágica apenas pela cor do umbigo ou esperar sua manifestação antes de reconhecer sangramento.", "avoid": "Não massagear nem provocar a área; a inspeção não deve atrasar ressuscitação e investigação de instabilidade.", "history": {"person": "Thomas Stephen Cullen", "period": "1918", "note": "Ginecologista; a descrição associava-se a gravidez ectópica rota. Há relatos anteriores de alterações semelhantes."}, "recall": {"question": "Cullen é exclusivo de pancreatite?", "answer": "Não. Deve ampliar a investigação de sangramento, inclusive vascular e ginecológico."}, "sources": ["cullen-vascular", "inspecao-historia"]}, {"id": "grey-turner", "name": "Sinal de Grey Turner", "aliases": ["equimose dos flancos"], "category": "Hemorragia e inspeção", "priority": "essencial", "anatomy": "Pele dos flancos, com possível origem em sangramento retroperitoneal ou outros planos profundos.", "position": "Decúbito dorsal ou lateral assistido, sem mobilizar desnecessariamente paciente instável.", "steps": ["Inspecione os dois flancos, levantando apenas o necessário dos lençóis ou roupas.", "Procure equimoses, mudanças progressivas de cor e assimetria.", "Investigue trauma, procedimentos, anticoagulantes e início da dor; examine também região periumbilical.", "Registre o achado junto da perfusão, pressão arterial e evolução clínica."], "positive": "Coloração equimótica de um ou ambos os flancos.", "mechanism": "Sangue e produtos de degradação podem dissecar planos fasciais até a parede lateral abdominal.", "interpretation": "Pode acompanhar hemorragia retroperitoneal e pancreatite grave, mas também aneurisma roto, trauma ou hematoma da parede.", "limits": "É raro e frequentemente tardio; sua ausência não oferece segurança contra hemorragia. A cor não data o início com precisão.", "pitfall": "Atribuir automaticamente ao pâncreas ou usar percentuais antigos de mortalidade como previsão individual.", "avoid": "Não virar repetidamente paciente com dor intensa, suspeita de trauma instável ou choque para completar a inspeção.", "history": {"person": "George Grey Turner", "period": "Descrição no início do século XX", "note": "Cirurgião britânico; datas de observação e publicação variam nas citações, portanto não são tratadas como equivalentes."}, "recall": {"question": "Qual localização distingue Grey Turner de Cullen?", "answer": "Grey Turner: flancos. Cullen: região periumbilical."}, "sources": ["grey-turner-ncbi", "inspecao-historia"]}, {"id": "fox", "name": "Sinal de Fox", "aliases": ["equimose proximal lateral da coxa"], "category": "Hemorragia e inspeção", "priority": "historico", "anatomy": "Face superolateral da coxa, geralmente abaixo do ligamento inguinal.", "position": "Inspeção dirigida com consentimento, preservando cobertura e intimidade.", "steps": ["Explique por que precisa observar a região proximal da coxa e exponha apenas a área necessária.", "Procure equimose com limite superior relativamente nítido, unilateral ou bilateral.", "Pergunte sobre trauma, injeção, acesso vascular ou lesão local que expliquem o aspecto.", "Integre o achado à presença de dor abdominal, sinais circulatórios e outras equimoses."], "positive": "Equimose não traumática na região proximal externa da coxa, em contexto clínico compatível.", "mechanism": "Sangue retroperitoneal pode progredir por planos fasciais e alcançar o subcutâneo abaixo da região inguinal.", "interpretation": "É uma pista histórica de sangramento profundo; já foi descrito em pancreatite e doença aneurismática.", "limits": "Muito raro, sem desempenho diagnóstico robustamente estabelecido. A morfologia isolada não informa origem nem volume do sangramento.", "pitfall": "Confundir com equimose da virilha por punção ou atribuir o epônimo ao dermatologista George Henry Fox.", "avoid": "Não ampliar exposição corporal sem necessidade nem retardar abordagem de choque para procurar um sinal raro.", "history": {"person": "J. A. Fox", "period": "1966", "note": "Cirurgião que relatou o achado em dois pacientes; esta fonte não sustenta atribuição a George Henry Fox."}, "recall": {"question": "O que a presença de Fox permite concluir?", "answer": "Que é necessário considerar sangramento profundo; não permite identificar a causa sozinho."}, "sources": ["inspecao-historia", "fox-original"]}, {"id": "kehr", "name": "Sinal de Kehr", "aliases": ["dor referida no ombro esquerdo"], "category": "Hemorragia e dor referida", "priority": "essencial", "anatomy": "Irritação do hemidiafragma esquerdo e aferências do nervo frênico, percebidas como dor no ombro.", "position": "Observe na posição espontânea; não é necessário provocar o sinal com inclinação do leito.", "steps": ["Em dor abdominal ou trauma, pergunte se há dor nova no ombro esquerdo ou na região supraclavicular.", "Verifique relação temporal e diferencie de trauma direto, dor articular e esforço muscular.", "Examine abdome e perfusão sem pressionar vigorosamente o hipocôndrio esquerdo.", "Se houver suspeita de hemoperitônio, integre a avaliação clínica à ultrassonografia e à avaliação cirúrgica conforme estabilidade."], "positive": "Dor referida no ombro esquerdo em contexto compatível com irritação diafragmática.", "mechanism": "A convergência de aferências cervicais do frênico favorece percepção da dor em território do ombro.", "interpretation": "Pode acompanhar lesão esplênica ou sangue intraperitoneal; outras causas subdiafragmáticas também são possíveis.", "limits": "Nem toda lesão esplênica produz o sinal e nem toda dor no ombro é abdominal. Não localiza exclusivamente o baço.", "pitfall": "Esperar dor no ombro para suspeitar de sangramento ou provocar Trendelenburg apenas para demonstrar o epônimo.", "avoid": "Não deslocar paciente instável ou traumatizado com finalidade didática; priorize segurança e avaliação urgente.", "history": {"person": "Hans Kehr — associação epônima tradicional", "period": "Transição dos séculos XIX–XX", "note": "A formulação moderna difere de algumas descrições históricas; não se afirma prioridade absoluta."}, "recall": {"question": "Por que o ombro pode doer quando o problema está no abdome?", "answer": "Porque a irritação diafragmática pode gerar dor referida através de aferências do frênico."}, "sources": ["kehr-caso", "inspecao-historia"]}, {"id": "chilaiditi", "name": "Sinal de Chilaiditi — diferencial radiológico", "aliases": ["interposição hepatodiafragmática do cólon", "pseudopneumoperitônio"], "category": "Correlação com imagem", "priority": "complementar", "anatomy": "Alça intestinal interposta entre o fígado e o hemidiafragma direito.", "position": "Não é manobra de exame físico. A identificação depende de radiografia ou tomografia.", "steps": ["Ao encontrar perda da macicez hepática ou gás subdiafragmático, mantenha o diferencial entre ar livre e ar dentro de alça.", "Na imagem, procure contornos intestinais e haustrações com apoio do radiologista.", "Relacione o achado à clínica: incidental sem sintomas é sinal; sintomas atribuídos à interposição configuram síndrome.", "Se houver dúvida ou sinais de complicação, prossiga a investigação apropriada sem presumir benignidade."], "positive": "Demonstração por imagem de intestino entre fígado e diafragma.", "mechanism": "Variações anatômicas, mobilidade colônica e distensão permitem ocupar um espaço normalmente sem alça.", "interpretation": "Explica alguns quadros de pseudopneumoperitônio e pode evitar intervenção desnecessária quando corretamente reconhecido.", "limits": "O achado pode coexistir com doença verdadeira; dor intensa, peritonismo ou instabilidade exigem investigação de complicações.", "pitfall": "Chamar Chilaiditi de sinal palpável, ou concluir que todo gás subdiafragmático com uma alça visível é inofensivo.", "avoid": "Não usar o rótulo para ignorar suspeita de perfuração, obstrução ou isquemia.", "history": {"person": "Demetrius Chilaiditi", "period": "1910", "note": "Radiologista. Esta entrada fica separada dos sinais físicos para evitar erro de categoria."}, "recall": {"question": "Qual diferença entre sinal e síndrome de Chilaiditi?", "answer": "Sinal é a imagem; síndrome implica sintomas relacionados ao achado."}, "sources": ["chilaiditi"]}, {"id": "dance", "name": "Sinal de Dance", "aliases": ["fossa ilíaca direita aparentemente vazia"], "category": "Obstrução e sinais históricos", "priority": "historico", "anatomy": "Região ileocecal e segmento intestinal deslocado por invaginação.", "position": "Inspeção e palpação leve em posição confortável.", "steps": ["Observe contorno abdominal, assimetria e eventual depressão relativa da fossa ilíaca direita.", "Quando tolerado, palpe suavemente procurando massa abdominal e registre sua localização.", "Relacione o achado a crises de dor, vômitos, letargia ou sangue nas fezes, sem esperar uma combinação completa.", "Encaminhe a suspeita de invaginação à confirmação por imagem, com prioridade conforme o estado clínico."], "positive": "Descrição clássica de relativo esvaziamento da fossa ilíaca direita associado ao deslocamento da massa ileocecal.", "mechanism": "A invaginação pode retirar parte do conteúdo da região habitual e criar uma massa em outro segmento abdominal.", "interpretation": "Pista histórica de intussuscepção, sobretudo pediátrica, com apresentação variável.", "limits": "Não é suficientemente sensível para excluir invaginação e não deve ser considerado patognomônico no ensino atual.", "pitfall": "Exigir massa, dor e fezes em 'geleia' simultaneamente ou tratar uma fossa aparentemente vazia como confirmação diagnóstica.", "avoid": "Não comprimir vigorosamente a massa, tentar reduzir manualmente por palpação abdominal ou atrasar imagem procurando o sinal.", "history": {"person": "Jean Baptiste Hippolyte Dance", "period": "Descrição de 1826", "note": "Médico francês. A documentação histórica e a literatura posterior usam descrições nem sempre uniformes."}, "recall": {"question": "Dance ausente exclui intussuscepção?", "answer": "Não. A suspeita depende do quadro clínico e exige confirmação apropriada."}, "sources": ["dance-radionuclideo", "inspecao-historia"]}, {"id": "torres-homem", "name": "Sinal de Torres-Homem", "aliases": ["dor focal à percussão hepática"], "category": "Hepatobiliar", "priority": "historico", "anatomy": "Região hepática e cápsula/peritônio adjacentes.", "position": "Decúbito dorsal, examinador à direita.", "steps": ["Pergunte sobre localização da dor, febre e limitações antes de tocar.", "Percuta de forma muito suave a área hepática, começando longe do ponto mais sensível.", "Observe se existe dor focal marcadamente maior em uma região e interrompa quando reconhecida.", "Descreva a localização e associe o achado ao restante da investigação hepatobiliar."], "positive": "Dor localizada e intensa mesmo à percussão suave de uma área hepática.", "mechanism": "Inflamação local ou distensão capsular pode tornar a transmissão do pequeno impacto dolorosa.", "interpretation": "A tradição semiológica associa o sinal ao abscesso hepático; outras causas de dor hepática/peritoneal precisam ser consideradas.", "limits": "Não há desempenho diagnóstico suficiente para confirmar abscesso por este sinal; ultrassonografia/tomografia e contexto infeccioso são decisivos.", "pitfall": "Interpretar 'intensamente dolorosa' como ordem para percutir intensamente. A intensidade é da resposta, não da força aplicada.", "avoid": "Nunca executar golpes fortes ou repetir a provocação; dor importante já presente dispensa a manobra.", "history": {"person": "João Vicente Torres Homem — atribuição tradicional", "period": "Século XIX; fonte original não confirmada", "note": "Médico clínico brasileiro. A nomenclatura foi confirmada em manual universitário, sem verificação da prioridade histórica."}, "recall": {"question": "Torres-Homem exige percussão forte?", "answer": "Não. Deve-se usar percussão suave e valorizar a dor provocada sem aumentá-la."}, "sources": ["unila-manual", "clinmethods-exame"]}, {"id": "lemos-torres", "name": "Manobra de Lemos Torres", "aliases": ["palpação hepática bimanual", "Chauffard — denominação associada em alguns manuais"], "category": "Hepatobiliar", "priority": "complementar", "anatomy": "Borda inferior do fígado, especialmente lobo direito, mobilizada pela respiração.", "position": "Decúbito dorsal; examinador à direita.", "steps": ["Apoie a mão esquerda na região lombar direita, junto às últimas costelas, para oferecer suporte posterior suave.", "Coloque a mão direita espalmada no abdome, inicialmente abaixo da borda hepática esperada.", "Durante a inspiração lenta, aguarde a borda descer até as polpas digitais; ajuste a mão durante a expiração seguinte.", "Descreva borda fina ou romba, superfície, consistência, dor e distância do rebordo na linha examinada."], "positive": "Não é um sinal binário; o resultado é a caracterização do fígado palpável.", "mechanism": "O suporte posterior e a descida inspiratória favorecem o contato da borda com a mão anterior.", "interpretation": "Auxilia a reconhecer hepatomegalia, alterações de consistência e sensibilidade no conjunto do exame.", "limits": "Fígado palpável não significa necessariamente aumento: biotipo e deslocamento inferior interferem. A palpação não substitui medida por imagem.", "pitfall": "Confundir uma borda palpável abaixo das costelas com hepatomegalia sem considerar o limite superior e o contexto.", "avoid": "Não tentar elevar o órgão com força ou comprimir contra dor/defesa; adapte o posicionamento à mobilidade do examinador e do paciente.", "history": {"person": "Lemos Torres — atribuição tradicional", "period": "Século XX; descrição inicial não confirmada", "note": "Manuais brasileiros também associam o método a Chauffard; não se afirma que as variantes sejam historicamente idênticas."}, "recall": {"question": "Qual a função da mão posterior?", "answer": "Apoiar e aproximar suavemente a região hepática da mão anterior."}, "sources": ["unila-manual", "stanford-figado"]}, {"id": "mathieu", "name": "Manobra de Mathieu", "aliases": ["palpação hepática em garra", "técnica em gancho do fígado"], "category": "Hepatobiliar", "priority": "complementar", "anatomy": "Borda inferior do fígado junto ao rebordo costal direito.", "position": "Decúbito dorsal; examinador à direita, orientado para os pés do paciente.", "steps": ["Explique que a palpação será feita com as pontas dos dedos levemente fletidas, sem agarrar a pele.", "Posicione as duas mãos abaixo do rebordo costal direito, ajustando o apoio ao biotipo.", "Durante a expiração, acomode os dedos suavemente; peça uma inspiração lenta e aguarde a borda hepática encontrá-los.", "Registre textura, contorno e dor, interrompendo se a posição dos dedos produzir desconforto excessivo."], "positive": "Técnica de palpação, sem positividade binária: o resultado é a borda hepática percebida e suas características.", "mechanism": "A disposição em gancho oferece outra superfície de contato para a descida inspiratória do fígado.", "interpretation": "Alternativa à palpação espalmada/bimanual quando a técnica facilita o contato, sem substituir avaliação do tamanho global.", "limits": "Não palpar a borda não indica ausência de hepatomegalia; fígado palpável pode ser normal ou estar deslocado inferiormente.", "pitfall": "Usar 'garra' como instrução de força ou confundir a palpação de fígado com Murphy vesicular.", "avoid": "Não introduzir dedos profundamente sob costelas dolorosas nem repetir várias técnicas se a primeira já trouxe informação suficiente.", "history": {"person": "Epônimo Mathieu; atribuição individual não confirmada", "period": "Propedêutica clássica", "note": "A nomenclatura do manual brasileiro foi preservada sem criar biografia ou reivindicação de descoberta."}, "recall": {"question": "O que se descreve ao palpar o fígado?", "answer": "Borda, superfície, consistência, sensibilidade e posição em relação ao rebordo."}, "sources": ["unila-manual", "stanford-figado"]}, {"id": "posicao-antalgica", "name": "Inclinação anterior e posição genupeitoral antálgica", "aliases": ["posição de prece — expressão histórica", "posição fetal", "genupeitoral"], "category": "Inspeção e comportamento da dor", "priority": "complementar", "anatomy": "Postura global do paciente e relação entre movimento, parede abdominal e dor profunda.", "position": "A que o paciente espontaneamente considera confortável; inclinação anterior, flexão do tronco ou joelhos próximos ao tórax.", "steps": ["Observe a postura antes de pedir qualquer mudança e pergunte qual posição melhora ou piora a dor.", "Distinga sentar inclinado para frente, encolher-se em posição fetal e apoiar joelhos/tórax: não são posturas idênticas.", "Permita acomodação segura, sem exigir que a pessoa execute uma posição religiosa ou forçada.", "Documente o alívio referido, a topografia da dor e os sintomas associados, mantendo investigação conforme gravidade."], "positive": "Não há teste padronizado positivo: interessa o relato de alívio ou agravamento da dor com a postura.", "mechanism": "Mudanças na tensão de estruturas abdominais podem modificar a percepção dolorosa; o mecanismo exato não define uma etiologia.", "interpretation": "Inclinar-se para frente ou aproximar joelhos do tórax pode aliviar dor de pancreatite em alguns pacientes.", "limits": "A postura não confirma pancreatite e o alívio não afasta doença grave. Genupeitoral não é requisito diagnóstico.", "pitfall": "Chamar toda inclinação anterior de genupeitoral ou tratar 'prece maometana' como sinal específico e obrigatório.", "avoid": "Não impor postura desconfortável, culturalmente inadequada ou insegura, sobretudo com choque, dispneia ou limitação motora.", "history": {"person": "Descrição postural sem autor único", "period": "Terminologia clínica tradicional", "note": "Preferir termos anatômicos respeitosos; a expressão religiosa aparece apenas como alias histórico para compreensão."}, "recall": {"question": "Melhora ao inclinar-se confirma pancreatite?", "answer": "Não. É um dado da história que precisa de critérios clínicos, laboratoriais e/ou de imagem."}, "sources": ["nhs-pancreatite"]}, {"id": "charcot", "name": "Tríade biliar de Charcot", "aliases": ["febre, icterícia e dor no hipocôndrio direito"], "category": "Síndromes hepatobiliares", "priority": "essencial", "anatomy": "Vias biliares associadas a resposta inflamatória sistêmica; reúne sintomas e sinais.", "position": "Avaliação clínica global, sem manobra provocativa obrigatória.", "steps": ["Investigue dor no hipocôndrio direito e sua evolução, sem limitar a história a uma palpação.", "Verifique febre ou calafrios relatados e temperatura medida.", "Procure icterícia e integre colúria/acolia, exames de colestase e imagem biliar.", "Diante de suspeita de colangite, avalie gravidade e organize abordagem urgente sem aguardar a tríade completa."], "positive": "Presença conjunta de febre, icterícia e dor no quadrante superior direito.", "mechanism": "Obstrução e infecção biliar podem causar colestase, dor e manifestação sistêmica.", "interpretation": "Conjunto clássico sugestivo de colangite aguda; útil como alerta e como integração entre história e exame.", "limits": "Sensibilidade insuficiente, especialmente em idosos e apresentações atípicas. Critérios atuais consideram inflamação, colestase e imagem.", "pitfall": "Excluir colangite pela falta de um componente ou confundir esta tríade com outros epônimos de Charcot em neurologia.", "avoid": "Não atrasar investigação e manejo esperando febre documentada ou icterícia evidente; não aplicar manobras dolorosas desnecessárias.", "history": {"person": "Jean-Martin Charcot", "period": "Século XIX", "note": "Neurologista e clínico francês; o epônimo não corresponde a um sinal cirúrgico isolado."}, "recall": {"question": "A tríade precisa estar completa para suspeitar colangite?", "answer": "Não. Sua ausência parcial é frequente e não afasta a doença."}, "sources": ["tg18-validacao", "colangite-idades"]}, {"id": "reynolds", "name": "Pêntade de Reynolds", "aliases": ["tríade de Charcot com hipotensão e alteração mental"], "category": "Síndromes hepatobiliares", "priority": "essencial", "anatomy": "Infecção biliar com repercussão circulatória e neurológica sistêmica.", "position": "Avaliação à beira-leito, com monitorização conforme o quadro.", "steps": ["Identifique sinais de infecção/obstrução biliar a partir da história, exame e exames disponíveis.", "Avalie pressão arterial e perfusão, considerando tendências e não apenas uma medida.", "Examine nível de consciência e compare com o estado habitual; procure explicações concorrentes.", "Na presença de disfunção orgânica, priorize suporte, investigação do foco e discussão de controle da fonte sem esperar todos os componentes."], "positive": "Associação clássica de dor biliar, febre, icterícia, hipotensão e alteração do estado mental.", "mechanism": "Infecção biliar importante pode levar à resposta sistêmica e disfunção de órgãos.", "interpretation": "Sinaliza apresentação grave que exige abordagem urgente; não é necessário completar a pêntade para reconhecer gravidade.", "limits": "É pouco sensível; confusão e hipotensão têm múltiplas causas. Classificações contemporâneas avaliam disfunções específicas.", "pitfall": "Tratar a pêntade como critério obrigatório de sepse, choque séptico ou necessidade de avaliação de drenagem.", "avoid": "Não retardar suporte e avaliação especializada enquanto se procura icterícia ou dor típica em paciente já instável.", "history": {"person": "Benedict M. Reynolds; Everett L. Dargan", "period": "Descrição clássica de 1959", "note": "O nome corrente abrevia uma descrição em coautoria; o conteúdo deve ser usado como alerta clínico."}, "recall": {"question": "Qual mensagem prática da pêntade?", "answer": "Reconhecer repercussão sistêmica grave; não esperar que todos os sinais apareçam."}, "sources": ["tg18-validacao", "colangite-idades", "reynolds-original"]}, {"id": "virchow-troisier", "name": "Linfonodo de Virchow e sinal de Troisier", "aliases": ["adenomegalia supraclavicular esquerda"], "category": "Exame ampliado e neoplasia", "priority": "complementar", "anatomy": "Fossa supraclavicular esquerda, próxima à drenagem do ducto torácico.", "position": "Sentado ou semissentado, ombros relaxados.", "steps": ["Explique a avaliação fora do abdome e inspecione ambas as fossas supraclaviculares.", "Palpe delicadamente com polpas digitais, sem comprimir estruturas vasculares.", "Descreva tamanho aproximado, consistência, mobilidade, sensibilidade e pele.", "Relacione o achado a perda ponderal, sintomas digestivos, torácicos e outras cadeias linfonodais; organize investigação dirigida."], "positive": "Linfonodo supraclavicular esquerdo aumentado, especialmente duro e pouco móvel, despertando suspeita de doença relevante.", "mechanism": "A drenagem linfática do tórax, abdome e pelve pode levar doença à região supraclavicular esquerda.", "interpretation": "Pode sugerir neoplasia intra-abdominal, torácica ou outra doença sistêmica; não é exclusivo de câncer gástrico.", "limits": "A etiologia exige avaliação adicional e, em casos selecionados, amostragem tecidual. Ausência não exclui câncer.", "pitfall": "Anunciar metástase gástrica ao paciente apenas com base na palpação.", "avoid": "Não apertar ou massagear a massa; não atribuir malignidade sem confirmação e comunicação cuidadosa.", "history": {"person": "Rudolf Virchow; Charles-Émile Troisier", "period": "Século XIX", "note": "Virchow era patologista e médico; Troisier era médico. O linfonodo e sua expressão clínica têm histórias relacionadas."}, "recall": {"question": "Por que examinar o pescoço em semiologia abdominal?", "answer": "Porque sinais extra-abdominais podem revelar processos sistêmicos ou linfáticos associados."}, "sources": ["virchow-anatomia"]}, {"id": "mary-joseph", "name": "Nódulo da Irmã Mary Joseph", "aliases": ["Sister Mary Joseph nodule", "nódulo umbilical metastático"], "category": "Exame ampliado e neoplasia", "priority": "complementar", "anatomy": "Umbigo e região periumbilical superficial.", "position": "Inspeção e palpação leve em posição confortável.", "steps": ["Observe o umbigo em busca de nódulo novo, irregularidade, ulceração ou secreção.", "Pergunte sobre evolução, crescimento, sangramento, dor e sintomas gerais.", "Palpe delicadamente para descrever consistência e relação com a parede, sem tentar reduzir uma massa suspeita.", "Solicite investigação adequada para distinguir metástase, hérnia, endometriose, infecção e lesões cutâneas benignas."], "positive": "O epônimo se aplica ao nódulo umbilical metastático; clinicamente, uma lesão suspeita ainda precisa de confirmação.", "mechanism": "Neoplasias abdominais ou pélvicas podem atingir o umbigo por diferentes vias de disseminação.", "interpretation": "É um achado relevante que pode ser a primeira manifestação de neoplasia ou recorrência.", "limits": "Nem todo nódulo umbilical é metástase; confirmação histológica e investigação do primário são necessárias.", "pitfall": "Confundir suspeita visual com diagnóstico histopatológico ou presumir que um nódulo é sempre hérnia.", "avoid": "Não manipular agressivamente, reduzir à força ou atribuir prognóstico individual por aparência.", "history": {"person": "Irmã Mary Joseph Dempsey", "period": "Epônimo difundido por Hamilton Bailey em 1949", "note": "Enfermeira e assistente cirúrgica, não cirurgiã. O nome reconhece sua observação clínica, sem afirmar primeira descrição absoluta."}, "recall": {"question": "Qual erro histórico este epônimo ajuda a evitar?", "answer": "Supor que todos os sinais epônimos foram descobertos por cirurgiões."}, "sources": ["mary-joseph-casos", "mary-joseph-diferencial", "mary-joseph-historia"]}, {"id": "ballance", "name": "Sinal de Ballance", "aliases": ["macicez fixa à esquerda e móvel à direita"], "category": "Hemorragia e sinais históricos", "priority": "historico", "anatomy": "Regiões esplênica e dos flancos, no contexto de possível hemoperitônio.", "position": "Descrição clássica compara decúbitos; atualmente a segurança e a estabilidade determinam se há exame postural.", "steps": ["Reconheça primeiro trauma, dor no hipocôndrio esquerdo e sinais de sangramento.", "Se o paciente estiver estável e o exame já incluir percussão, descreva macicez nos flancos com técnica suave.", "A descrição clássica é de macicez esquerda persistente e componente direito que se desloca com a posição.", "Não procure completar a manobra em instabilidade; registre os achados existentes e priorize ultrassonografia/avaliação do trauma."], "positive": "Combinação histórica de macicez fixa no flanco esquerdo e móvel à direita.", "mechanism": "Foi atribuída a coágulos próximos ao baço e sangue mais livre em outras regiões; é uma explicação histórica.", "interpretation": "Associado tradicionalmente à ruptura esplênica, com valor atual sobretudo de compreensão histórica da percussão.", "limits": "Não há validação suficiente para tratá-lo como patognomônico, e a ausência não exclui hemorragia.", "pitfall": "Usar a descrição clássica para atrasar imagem, ou chamar qualquer massa dolorosa esquerda de Ballance.", "avoid": "Não girar paciente traumatizado ou instável para demonstrar mobilidade de macicez, nem comprimir região esplênica.", "history": {"person": "Charles Alfred Ballance", "period": "1898", "note": "Cirurgião britânico; afirmações antigas de exclusividade e mecanismo devem ser lidas como história, não evidência atual."}, "recall": {"question": "Qual valor atual deve ser atribuído a Ballance?", "answer": "Histórico e descritivo; não um critério para decidir sozinho sobre sangramento ou cirurgia."}, "sources": ["percussao-historia"]}, {"id": "rosenstein", "name": "Sinal de Rosenstein", "aliases": ["dor à direita maior em decúbito lateral esquerdo", "Sitkovskiy — denominação relacionada"], "category": "Apendicular e sinais históricos", "priority": "historico", "anatomy": "Região cecoapendicular e tecidos deslocados pela mudança de decúbito.", "position": "Comparação entre decúbito dorsal e lateral esquerdo, apenas quando tolerada.", "steps": ["Registre a localização da dor e a sensibilidade em decúbito dorsal sem repetição desnecessária.", "Se houver utilidade clínica, ajude o paciente a assumir decúbito lateral esquerdo com segurança.", "Observe a dor espontânea e, somente se necessário, compare palpação leve da mesma região direita.", "Documente se a mudança ocorreu com a posição ou com a pressão, pois as descrições do epônimo variam."], "positive": "Aumento da dor/sensibilidade na região inferior direita em decúbito lateral esquerdo, na descrição tradicional.", "mechanism": "O deslocamento gravitacional pode aumentar tensão em tecidos inflamados; mecanismo e técnica não são padronizados.", "interpretation": "Pista histórica relacionada à apendicite; não deve substituir sinais mais úteis ou a investigação apropriada.", "limits": "Pouca validação e sobreposição com outros epônimos; o sinal não localiza a posição do apêndice com segurança.", "pitfall": "Acumular nomes diferentes para o mesmo desconforto sem descrever o gesto efetivamente realizado.", "avoid": "Não mover paciente instável ou provocar repetidamente dor para colecionar sinais apendiculares.", "history": {"person": "Paul Rosenstein — associação descrita na revisão histórica", "period": "1920", "note": "Há nomes relacionados em diferentes tradições. A equivalência entre todas as variantes não é assumida."}, "recall": {"question": "O que registrar quando um epônimo tem técnicas variáveis?", "answer": "O decúbito, o local examinado e a resposta, além do nome."}, "sources": ["palpacao-historia-2"]}, {"id": "migracao-kocher", "name": "Migração da dor — Volkovich–Kocher", "aliases": ["migração periumbilical para fossa ilíaca direita", "Kocher–Volkovich"], "category": "Apendicular e história clínica", "priority": "essencial", "anatomy": "Transição entre aferência visceral mal localizada e irritação somática do peritônio parietal.", "position": "Anamnese; não exige provocação física.", "steps": ["Pergunte onde a dor começou antes de perguntar onde está mais intensa agora.", "Estabeleça a sequência temporal entre dor, mudança de localização, náuseas e vômitos.", "Peça que o paciente diferencie migração da dor de simples irradiação para outro local.", "Relacione essa evolução ao exame atual, aos diagnósticos alternativos e à necessidade de reavaliação."], "positive": "História de dor inicialmente central/periumbilical ou epigástrica que passa a predominar na fossa ilíaca direita.", "mechanism": "A dor visceral inicial pode tornar-se localizada quando a inflamação alcança o peritônio parietal adjacente.", "interpretation": "É um dado útil a favor de apendicite, especialmente quando coerente com dor focal e inflamação.", "limits": "A sequência clássica falta em muitos pacientes; localização atípica e informação incompleta não excluem a doença.", "pitfall": "Reescrever retrospectivamente a história para fazê-la caber no padrão clássico ou considerar migração igual a irradiação.", "avoid": "Não esperar migração para solicitar avaliação de paciente com dor progressiva, defesa ou deterioração.", "history": {"person": "Nikolai Volkovich; Emil Theodor Kocher", "period": "Transição dos séculos XIX–XX", "note": "Epônimos variam entre tradições; o fenômeno clínico deve ser explicado antes da atribuição histórica."}, "recall": {"question": "Qual diferença entre migrar e irradiar?", "answer": "Na migração muda o local predominante ao longo do tempo; irradiação descreve extensão a outro território."}, "sources": ["palpacao-historia-2", "apendicite-ncbi"]}, {"id": "rigidez", "name": "Defesa involuntária e abdome em tábua", "aliases": ["rigidez abdominal", "contratura involuntária"], "category": "Irritação peritoneal", "priority": "essencial", "anatomy": "Musculatura da parede em resposta à irritação peritoneal; deve ser diferenciada de contração voluntária.", "position": "Decúbito dorsal confortável; joelhos apoiados e mãos aquecidas.", "steps": ["Observe imobilidade, respiração superficial e proteção da região dolorosa antes de tocar.", "Comece palpação superficial em área distante da dor máxima e acompanhe a respiração.", "Converse e ajuste o conforto para reduzir ansiedade, sem usar surpresa ou engano.", "Registre resistência persistente localizada ou difusa; se já há peritonismo evidente, não acrescente descompressões repetidas."], "positive": "Resistência muscular persistente e involuntária; 'em tábua' descreve rigidez muito marcada.", "mechanism": "Reflexos de proteção acompanham irritação do peritônio e limitam movimentos dolorosos.", "interpretation": "É sinal de alerta para processo intra-abdominal importante e necessidade de avaliação urgente, conforme contexto.", "limits": "Pode faltar em idosos, imunossuprimidos e pacientes com resposta muscular reduzida. Nem toda parede tensa é peritonite.", "pitfall": "Confundir ansiedade, cócegas, musculatura forte ou dor de parede com rigidez involuntária; exame 'flácido' não exclui emergência.", "avoid": "Não vencer a resistência com força nem tratar o achado como autorização para adiar analgesia.", "history": {"person": "Expressão descritiva, sem autor único", "period": "Propedêutica clássica", "note": "O valor vem da resposta observada e da evolução clínica, não de um nome próprio."}, "recall": {"question": "Se há rigidez evidente, é obrigatório pesquisar Blumberg repetidamente?", "answer": "Não. O achado já pode orientar a decisão e deve limitar provocações dolorosas."}, "sources": ["msd-dor-aguda", "clinmethods-exame"]}, {"id": "ruidos-intestinais", "name": "Ruídos intestinais, timbres agudos e silêncio abdominal", "aliases": ["ruídos hidroaéreos", "ruídos metálicos", "ausculta abdominal"], "category": "Ausculta e obstrução", "priority": "essencial", "anatomy": "Movimentos de gás e líquido no tubo digestivo transmitidos à parede.", "position": "Decúbito confortável, ambiente silencioso e diafragma do estetoscópio aquecido.", "steps": ["Ausculte antes de manipulação abdominal extensa, mantendo contato leve do diafragma.", "Ouça em mais de uma região e descreva presença, regularidade e caráter dos sons.", "Se não ouvir imediatamente, prolongue a observação conforme contexto; poucos segundos sem ruído não definem silêncio.", "Relacione o achado a dor, distensão, vômitos, eliminação de fezes/gases, cirurgias e imagem."], "positive": "Não há positividade única: descreva sons presentes, hiperativos/agudos ou persistentemente não auscultados.", "mechanism": "Fluxo e movimentação luminal geram sons; obstrução, íleo, inflamação e muitos fatores fisiológicos alteram o padrão.", "interpretation": "Contribui para descrição do exame, mas não confirma nem exclui obstrução ou isquemia.", "limits": "Estudo prospectivo mostrou baixa acurácia e concordância entre observadores. Sons podem persistir em quadros graves.", "pitfall": "Decidir que o intestino está 'funcionando normalmente' só porque há ruídos, ou adiar imagem porque eles não são metálicos.", "avoid": "Não atrasar decisões urgentes para completar longos períodos de ausculta em paciente instável.", "history": {"person": "Técnica coletiva; epônimos não necessários", "period": "Uso clínico há mais de um século", "note": "Termos históricos não tornam a ausculta um teste diagnóstico autossuficiente."}, "recall": {"question": "Ruídos presentes excluem obstrução intestinal?", "answer": "Não. A decisão deve integrar história, exame global e investigação."}, "sources": ["ausculta-estudo"]}, {"id": "massa-pulsatil", "name": "Massa abdominal pulsátil e suspeita de aneurisma", "aliases": ["pulsatilidade expansiva", "aneurisma de aorta abdominal — suspeita clínica"], "category": "Vascular e segurança", "priority": "essencial", "anatomy": "Aorta abdominal e massas que podem receber pulsação transmitida.", "position": "Posição confortável; exame restrito ao necessário, especialmente se houver dor ou instabilidade.", "steps": ["Pergunte sobre dor nova abdominal/lombar, síncope e aneurisma conhecido; verifique perfusão.", "Observe a região abdominal e reconheça pulsação ou massa sem pressão profunda insistente.", "Se houver suspeita de aneurisma sintomático, solicite avaliação urgente e ultrassonografia à beira-leito quando disponível.", "Registre limitações do exame e evite repetir palpação apenas para demonstrar expansibilidade."], "positive": "Massa pulsátil levanta suspeita vascular, principalmente quando acompanhada de dor, síncope ou instabilidade.", "mechanism": "Dilatação aórtica pode gerar pulso expansivo; massa não vascular pode apenas transmitir a pulsação.", "interpretation": "É um alerta para aneurisma, que requer confirmação e definição de urgência; a tríade clássica pode estar incompleta.", "limits": "Obesidade e anatomia dificultam a palpação; não encontrar massa não exclui aneurisma roto. A clínica não mede diâmetro com precisão.", "pitfall": "Chamar toda pulsação visível de aneurisma ou considerar dor lombar isolada necessariamente musculoesquelética.", "avoid": "Não comprimir vigorosamente massa pulsátil nem atrasar discussão vascular se ultrassonografia for indisponível ou inconclusiva.", "history": {"person": "Achado descritivo, sem atribuição única", "period": "Prática clínica contemporânea", "note": "A prioridade é reconhecer a emergência; manobras epônimas adicionais raramente mudam a necessidade de imagem."}, "recall": {"question": "A ausência de massa palpável afasta ruptura de aneurisma?", "answer": "Não. Dor nova, síncope ou colapso circulatório podem ser a apresentação."}, "sources": ["nice-aorta"]}], "visuals": [{"id": "A01", "title": "Preparo e posicionamento", "alt": "Pessoa adulta vestida, em decúbito dorsal, cabeça apoiada e joelhos levemente fletidos, acompanhada por examinador.", "caption": "A cena ilustra o posicionamento antes da exposição do abdome: decúbito dorsal, cabeça apoiada e joelhos levemente fletidos. Para examinar, exponha somente a área necessária, com consentimento e privacidade.", "steps": ["Explique o exame, obtenha consentimento e ofereça privacidade.", "Apoie cabeça e joelhos; mantenha braços ao lado do corpo e mãos do examinador aquecidas.", "Pergunte onde dói antes de tocar e deixe a região dolorosa por último."], "positive": "Não há sinal positivo: é a preparação para um exame tolerável e reprodutível.", "limit": "Adapte a posição à dor, dispneia, trauma e condição hemodinâmica; o conforto não deve atrasar cuidados urgentes.", "suggestedSection": "Sequência do exame", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A01-preparo-supino.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "f856bdba82891725349ed7dcbcdab6769e3531c3ba1d619d4c9e618db72b5e48", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A02", "title": "Inspeção abdominal", "alt": "Olhar tangencial e iluminação lateral ajudam a perceber distensão, assimetrias e movimentos da parede. Observe também a pessoa: imobilidade por dor, agitação, respiração e sinais de sofrimento.", "caption": "A inspeção começa pela observação do contorno e do comportamento da pessoa. Complete a vista oblíqua ilustrada com observação frontal e tangencial para perceber distensão, assimetrias e movimentos da parede.", "steps": ["Observe o abdome de frente e pelos pés da maca.", "Abaixe o olhar até o plano da parede e examine o contorno com luz lateral.", "Descreva localização, simetria, cicatrizes, pele e movimentos; correlacione com a queixa."], "positive": "Distensão, abaulamento localizado, circulação colateral ou equimoses exigem interpretação contextual.", "limit": "A inspeção não identifica sozinha a causa de distensão nem distingue todos os quadros cirúrgicos.", "suggestedSection": "Sequência do exame", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A02-inspecao-tangencial.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "13020f6ed40813d5a9509594729f974771eb183a7649e581bb4b4dd7aa34b899", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A03", "title": "Ausculta abdominal", "alt": "Ausculta com o diafragma apoiado suavemente na pele, em ambiente silencioso, antes da palpação. Sons intestinais são intermitentes e a impressão de atividade aumentada ou reduzida deve ser integrada ao restante do exame.", "caption": "Ausculta com o diafragma apoiado suavemente na pele, em ambiente silencioso, antes da palpação. Sons intestinais são intermitentes e a impressão de atividade aumentada ou reduzida deve ser integrada ao restante do exame.", "steps": ["Coloque as olivas do estetoscópio corretamente e aqueça o diafragma.", "Apoie-o sem pressão excessiva e escute sistematicamente diferentes regiões.", "Registre o que ouviu e o contexto; não conclua obstrução ou íleo apenas pelo som."], "positive": "Ruídos de padrão alterado podem acompanhar diferentes doenças; sopros vasculares têm avaliação própria.", "limit": "Uma ausculta breve sem ruídos não comprova ausência de peristaltismo; desempenho isolado é limitado.", "suggestedSection": "Sequência do exame", "references": ["https://med.stanford.edu/e4c/benchmarks/_jcr_content/main/panel_builder_0/panel_1/download_5/file.res/Abdominal%20Benchmarks%20(updated%20August%202018).pdf"], "file": "assets/images/A03-ausculta-abdominal.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "9ab1068251fc22de060a5cca67a0d7fa6fbecbc4d7c64f92cab7eee88cb68e3b", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A04", "title": "Percussão: identifique o erro de padronização", "alt": "Exemplo de erro: examinador usa dedos indicadores na percussão digitodigital; o roteiro solicita corrigir para os dedos médios.", "caption": "EXEMPLO DE ERRO DE PADRONIZAÇÃO: a cena mostra os dedos indicadores. Na técnica ensinada neste curso, utilize o dedo médio como plexímetro e o dedo médio da outra mão como percussor. A imagem serve para reconhecer e corrigir a execução, não para copiá-la.", "steps": ["Identifique na imagem o uso dos indicadores e não reproduza essa escolha no treino padronizado.", "Corrija: apoie a falange distal do dedo médio na parede e afaste os demais dedos.", "Percuta o dedo apoiado com o médio da outra mão, punho solto e golpes breves; compare os sons com técnica consistente."], "positive": "Objetivo do exercício: detectar a escolha dos dedos e verbalizar a correção antes de praticar.", "limit": "Exemplo intencional de análise de erro. Não representa a técnica padronizada correta e não deve ser exibido sem este aviso.", "suggestedSection": "Sequência do exame", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A04-percussao-digitodigital.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "fab031831671cd1f8c04fccc1909b0c90c01094f667e89f0c5d345a902c64ac1", "teachingMode": "error-analysis", "width": 1672, "height": 941}, {"id": "A05", "title": "Palpação superficial", "alt": "A palpação superficial pesquisa sensibilidade e tensão da parede com pressão leve. Começar longe da dor reduz defesa voluntária e ajuda a separar apreensão de resistência persistente.", "caption": "A palpação superficial pesquisa sensibilidade e tensão da parede com pressão leve. Começar longe da dor reduz defesa voluntária e ajuda a separar apreensão de resistência persistente.", "steps": ["Pergunte onde a dor é máxima e inicie numa região distante.", "Aplique pressão suave com a face palmar dos dedos, percorrendo o abdome.", "Observe a face e diferencie sensibilidade, defesa voluntária e rigidez persistente."], "positive": "Dor localizada e resistência involuntária podem apoiar suspeita de irritação peritoneal.", "limit": "Ausência de defesa não exclui doença grave, especialmente em apresentações atípicas.", "suggestedSection": "Sequência do exame", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A05-palpacao-superficial.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "ecb63cf3cff20c67ba0b87f4ba03d4c7b7d8ca16dd6d89cc362b301a273d8cb0", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A06", "title": "Palpação profunda bimanual", "alt": "Uma mão pode reforçar a outra na palpação profunda para pesquisar massas e órgãos, após a etapa superficial. A pressão é progressiva e orientada pela tolerância, sem procurar dor a qualquer custo.", "caption": "Uma mão pode reforçar a outra na palpação profunda para pesquisar massas e órgãos, após a etapa superficial. A pressão é progressiva e orientada pela tolerância, sem procurar dor a qualquer custo.", "steps": ["Conclua a palpação superficial e reavalie a tolerância.", "Aprofunde gradualmente durante a expiração; use a segunda mão para controle se necessário.", "Descreva massa por localização, tamanho estimado, mobilidade, consistência e dor."], "positive": "Uma massa ou organomegalia é um achado descritivo que precisa de correlação e, frequentemente, imagem.", "limit": "Não force a palpação em dor intensa, rigidez ou massa pulsátil suspeita; a cena não representa pressão máxima.", "suggestedSection": "Sequência do exame", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A06-palpacao-profunda.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "80be9618287848972975c2598fcdd2c2fa766c35fcc4f35f4092ba0424ca0be0", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A07", "title": "Murphy: técnica subcostal direita", "alt": "A mão fica sob a margem costal direita, na projeção da vesícula, enquanto a pessoa inspira. O sinal clínico de Murphy corresponde à interrupção da inspiração por dor provocada nessa região.", "caption": "A mão fica sob a margem costal direita, na projeção da vesícula, enquanto a pessoa inspira. O sinal clínico de Murphy corresponde à interrupção da inspiração por dor provocada nessa região.", "steps": ["Posicione a pessoa em decúbito dorsal e localize a margem costal direita.", "Na expiração, aprofunde suavemente os dedos abaixo da margem, sem pressionar as costelas.", "Peça inspiração e observe se há parada inspiratória por dor; compare com o lado oposto quando apropriado."], "positive": "Parada inspiratória dolorosa à palpação subcostal direita aumenta a suspeita de colecistite no contexto compatível.", "limit": "Murphy clínico não é o Murphy ultrassonográfico; isoladamente não confirma nem exclui colecistite.", "suggestedSection": "Dor no hipocôndrio direito", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6306141/"], "file": "assets/images/A07-murphy.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "04a4e5973f23368673f463cba60d5151601377675442da711abfbe1614d9f3a4", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A08", "title": "Peritonismo: preparo para avaliação", "alt": "Pessoa vestida deitada, examinador posiciona a mão sobre o abdome coberto e observa sua expressão antes de prosseguir.", "caption": "A cena vestida mostra a comunicação e o posicionamento da mão antes da avaliação. A descompressão dolorosa é uma resposta dinâmica: a dor se acentua ao retirar a pressão e pode indicar irritação peritoneal, sem identificar a causa.", "steps": ["Procure primeiro dor à tosse, percussão delicada, defesa e rigidez.", "Se a informação ainda for necessária e a pessoa tolerar, comprima lentamente e observe a retirada da pressão.", "Interrompa diante de dor importante e registre topografia; evite repetir para demonstração."], "positive": "Dor maior na descompressão que na compressão é o achado tradicional associado a Blumberg.", "limit": "Não é específico de apendicite. Peritonismo evidente dispensa provocação repetida e deve orientar avaliação urgente. A imagem mostra preparação e não demonstra positividade.", "suggestedSection": "Peritonismo", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6546280/"], "file": "assets/images/A08-blumberg.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "28ed1ecc91a16ac2b7c44b23c8f5f63d615f9ba08240fbf9dc237139927d35d4", "teachingMode": "preparation", "width": 1672, "height": 941}, {"id": "A09", "title": "Rovsing: estímulo à esquerda", "alt": "Demonstração vestida: examinador apoia uma mão no quadrante inferior esquerdo; a pessoa aponta com sua própria mão a região inferior direita.", "caption": "Demonstração, sobre a roupa, das regiões envolvidas no teste: estímulo na fossa ilíaca esquerda e possível dor referida à direita. No exame clínico, faça a exposição abdominal apropriada com consentimento e privacidade; dor apenas à esquerda não constitui Rovsing.", "steps": ["Identifique direita e esquerda da pessoa, sem inverter pela perspectiva do examinador.", "Palpe suavemente a fossa ilíaca esquerda e pergunte onde a dor aparece.", "Registre se a dor é referida à direita, local ou ausente e integre ao restante da avaliação."], "positive": "Dor na fossa ilíaca direita provocada à esquerda pode apoiar irritação peritoneal associada a apendicite.", "limit": "A técnica original histórica difere de versões atuais; sinal negativo não exclui apendicite.", "suggestedSection": "Suspeita de apendicite", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6546280/"], "file": "assets/images/A09-rovsing.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "540d75251f064b24435e97d84b82fac28eb19b8a7cda3d50f3383d2edf9c45d8", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A10", "title": "Psoas: flexão contra resistência", "alt": "Esta é a variante de flexão ativa do quadril direito contra resistência leve. A contração do iliopsoas pode provocar dor abdominal quando estruturas adjacentes estão inflamadas.", "caption": "Esta é a variante de flexão ativa do quadril direito contra resistência leve. A contração do iliopsoas pode provocar dor abdominal quando estruturas adjacentes estão inflamadas.", "steps": ["Com a pessoa em decúbito dorsal, identifique o membro inferior direito.", "Peça que eleve a coxa enquanto aplica resistência leve sobre a face anterior distal da coxa.", "Pergunte se surge dor abdominal, diferenciando-a de dor muscular ou articular."], "positive": "Dor abdominal provocada pela manobra é um sinal de irritação do psoas no contexto clínico adequado.", "limit": "Não é exclusiva de apendicite; evitar esforço doloroso ou aplicação em suspeita de lesão musculoesquelética. A cena estática não demonstra a força aplicada nem uma resposta dolorosa positiva.", "suggestedSection": "Suspeita de apendicite", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6306146/"], "file": "assets/images/A10-psoas.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "d7e9fb0f34176f2e792ec4d64735e43a53157c11ab7ae00e1fc871e8fd259bb4", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A11", "title": "Obturador: posição inicial", "alt": "A cena mostra a posição inicial para o teste do obturador: quadril e joelho direitos fletidos. A rotação interna do quadril, realizada suavemente, pode tensionar o obturador interno próximo a estruturas pélvicas.", "caption": "A cena mostra a posição inicial para o teste do obturador: quadril e joelho direitos fletidos. A rotação interna do quadril, realizada suavemente, pode tensionar o obturador interno próximo a estruturas pélvicas.", "steps": ["Flexione quadril e joelho direitos aproximadamente a 90°, respeitando a mobilidade.", "Estabilize o joelho e desloque o tornozelo lateralmente para produzir rotação interna do quadril.", "Pergunte se há dor abdominal ou pélvica e diferencie de limitação articular."], "positive": "Dor hipogástrica ou em fossa ilíaca direita pode apoiar irritação pélvica no contexto suspeito.", "limit": "A fotografia estática não demonstra a rotação; ausência do sinal não exclui apendicite e dor do quadril pode confundir.", "suggestedSection": "Suspeita de apendicite", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6306146/"], "file": "assets/images/A11-obturador.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "d8b2c90f7717ff3a3c2b8162b646b0add97849e40b3d2dc24a789931534a25f3", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A12", "title": "Giordano: punhopercussão protegida", "alt": "A punhopercussão suave do ângulo costovertebral pesquisa dor nessa região. Uma mão interposta ajuda a controlar a intensidade; compare lados e considere causas renais e extrarrenais.", "caption": "A punhopercussão suave do ângulo costovertebral pesquisa dor nessa região. Uma mão interposta ajuda a controlar a intensidade; compare lados e considere causas renais e extrarrenais.", "steps": ["Posicione a pessoa sentada ou adapte ao leito e localize o ângulo costovertebral.", "Apoie uma mão na região e aplique um toque leve com a borda ulnar da outra mão.", "Pergunte sobre dor e compare com o outro lado, sem aumentar a força para obter resposta."], "positive": "Dor desencadeada no ângulo costovertebral é o achado positivo.", "limit": "Não confirma pielonefrite ou cálculo isoladamente. Diferencie de dor muscular, costal ou vertebral.", "suggestedSection": "Rins e retroperitônio", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A12-giordano.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "26f4c8e6e1fb4c2113b19309085c43f643676954c13b560280c09a126274f238", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A13", "title": "Israel: palpação renal em decúbito lateral", "alt": "A manobra de Israel utiliza decúbito lateral contrário ao rim examinado. Para pesquisar o rim direito, a pessoa fica sobre o lado esquerdo; as mãos anterior e posterior auxiliam a palpação bimanual.", "caption": "A manobra de Israel utiliza decúbito lateral contrário ao rim examinado. Para pesquisar o rim direito, a pessoa fica sobre o lado esquerdo; as mãos anterior e posterior auxiliam a palpação bimanual.", "steps": ["Deite a pessoa sobre o lado oposto ao rim que deseja examinar e ajuste o apoio.", "Posicione uma mão posteriormente na região lombar e a outra no abdome do lado examinado.", "Palpe com suavidade, acompanhando a respiração, e descreva eventual massa, mobilidade ou dor."], "positive": "Estrutura palpável precisa ser caracterizada e diferenciada de outros órgãos e massas.", "limit": "A palpação não identifica com segurança a natureza de uma massa; rim não palpável não exclui doença renal.", "suggestedSection": "Rins e retroperitônio", "references": ["https://www.sbp.com.br/fileadmin/user_upload/Manual_Uropediatria-Final.pdf"], "file": "assets/images/A13-israel.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "715f332fdfefcc14ec44aeaa289c1e95b99ad193a0984eb658a3913f5de1bcd1", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A14", "title": "Macicez móvel: mudança de decúbito", "alt": "Modelo humano adulto em decúbito lateral esquerdo, com flanco direito superior exposto e examinador ao lado, antes de repetir a percussão para pesquisar macicez móvel.", "caption": "A cena mostra a posição após mudar para decúbito lateral esquerdo, antes de repetir a percussão. O líquido livre tende a ocupar a região dependente. Compare o limite da macicez obtido em decúbito dorsal com o encontrado nessa nova posição; a imagem não demonstra o som nem a técnica dos dedos.", "steps": ["Em decúbito dorsal, percuta do centro timpânico para o flanco e identifique a transição.", "Mude para decúbito lateral, respeite a tolerância e aguarde a redistribuição.", "Percuta novamente a mesma região para verificar se o limite da macicez mudou. Na percussão indireta, apoie o dedo médio e golpeie sua falange média com a ponta do dedo médio da outra mão."], "positive": "Mudança da distribuição da macicez com a posição favorece líquido livre na cavidade.", "limit": "Ascite pequena, obesidade, loculações e técnica podem reduzir a utilidade; ultrassom esclarece dúvidas.", "suggestedSection": "Ascite", "references": ["https://med.stanford.edu/e4c/benchmarks/_jcr_content/main/panel_builder_0/panel_1/download_5/file.res/Abdominal%20Benchmarks%20(updated%20August%202018).pdf"], "file": "assets/images/A14-macicez-movel.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "d579a27e0cd2d227e3c03a0094bd34f046ed992d7e97a848e2e59007d6a3c726", "teachingMode": "positioning", "width": 1672, "height": 941}, {"id": "A15", "title": "Onda líquida: preparo para o bloqueio da parede", "alt": "Modelo humano adulto em decúbito dorsal com a própria mão em borda sobre o abdome e examinadora com uma mão em cada flanco, preparando a pesquisa da onda líquida.", "caption": "Preparação para a pesquisa da onda líquida: a própria pessoa mantém uma mão em borda sobre o abdome, e o examinador posiciona uma mão em cada flanco. Na cena, a mão própria ainda precisa ser reposicionada: alinhe sua borda ulnar exatamente à linha mediana que passa pelo umbigo antes de aplicar o impulso. A imagem não representa a execução final validada nem confirma ascite.", "steps": ["Em decúbito dorsal, peça à própria pessoa que apoie a borda da mão exatamente na linha média, passando sobre o umbigo; confira o alinhamento antes de iniciar.", "Posicione uma mão em cada flanco; aplique um impulso breve e suave de um lado.", "Perceba com a mão oposta se há transmissão e correlacione com outros sinais de ascite."], "positive": "Onda percebida no flanco oposto pode apoiar ascite de maior volume.", "limit": "A parede abdominal pode transmitir vibrações e produzir falso positivo; não substitui confirmação quando necessária.", "suggestedSection": "Ascite", "references": ["https://med.stanford.edu/e4c/benchmarks/_jcr_content/main/panel_builder_0/panel_1/download_5/file.res/Abdominal%20Benchmarks%20(updated%20August%202018).pdf"], "file": "assets/images/A15-onda-liquida.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "fa1b3b4672e70124daa605950ad2dcffb471cf6baca2ff0b73b7e33a6e98ce4f", "teachingMode": "preparation-realign-midline", "width": 1672, "height": 941}, {"id": "A16", "title": "Jobert: localização da área hepática", "alt": "Modelo anatômico humano 3D em decúbito dorsal, com projeção esquemática do fígado predominantemente no hipocôndrio direito, à esquerda de quem observa de frente; tórax e pelve cobertos.", "caption": "Modelo anatômico humano 3D para localizar a área hepática: o fígado ocupa principalmente o hipocôndrio direito, que aparece à esquerda de quem observa o corpo de frente. A sobreposição é esquemática e não representa um achado visível na pele. A imagem localiza a região de pesquisa; não demonstra a técnica das mãos nem um Jobert positivo. Na pesquisa tradicional, procura-se perda da macicez hepática esperada com substituição por timpanismo.", "steps": ["Identifique o hipocôndrio direito e a área de macicez hepática esperada, comparando a percussão de regiões próximas.", "Na percussão mediata, apoie somente a falange distal do dedo médio da mão não dominante sobre a pele; afaste os demais dedos e dê toques leves com a ponta do dedo médio da outra mão sobre o dedo apoiado.", "Descreva se a macicez foi substituída por timpanismo e integre o achado à dor e ao peritonismo. Não atrase investigação por imagem e avaliação cirúrgica quando indicadas."], "positive": "Timpanismo sobre a área habitualmente maciça do fígado corresponde ao achado tradicional.", "limit": "Não confirma pneumoperitônio; interposição de alças e variações da técnica podem imitá-lo. Um resultado normal não exclui perfuração.", "suggestedSection": "Perfuração e peritonismo", "references": ["https://med.stanford.edu/stanfordmedicine25/the25/liver.html"], "file": "assets/images/A16-jobert.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "8a50f0ebcbc8fae77d561af3a84efad8e078882a308b1c97c78386ce63a197f8", "teachingMode": "anatomical-landmark", "width": 1672, "height": 941}, {"id": "A17", "title": "Courvoisier: vesícula palpável e icterícia", "alt": "Pessoa adulta fictícia em decúbito dorsal, com discreta tonalidade ictérica, durante palpação subcostal suave; roupas e lençol cobrem as demais regiões.", "caption": "A cena ilustra palpação subcostal suave em pessoa com discreta tonalidade ictérica. A vesícula não é visível na pele: sua distensão e palpabilidade dependem do exame. Vesícula palpável, habitualmente indolor e associada à icterícia é o conjunto tradicional de Courvoisier, que exige investigação de obstrução biliar.", "steps": ["Observe escleras e pele para icterícia e caracterize sua evolução.", "Palpe com suavidade o hipocôndrio direito e descreva eventual massa e sensibilidade.", "Relacione o achado à colúria, hipocolia/acolia, prurido, perda ponderal e exames."], "positive": "Vesícula palpável e indolor associada à icterícia é a combinação clínica relevante.", "limit": "Não é uma lei de malignidade: há causas benignas e sua ausência não afasta neoplasia.", "suggestedSection": "Dor no hipocôndrio direito", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6306141/"], "file": "assets/images/A17-courvoisier.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "c32abf76ccf51836d6bfdc834a7d996769920ef8b3c35cbd0adc90b325223df0", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A18", "title": "Cullen: equimose periumbilical", "alt": "Ilustração clínica sintética de equimose irregular arroxeada ao redor do umbigo, com pele íntegra e drapeamento do tórax e da pelve.", "caption": "Equimose ao redor do umbigo é o sinal de Cullen. O sangue pode alcançar o tecido subcutâneo a partir de diferentes origens; o achado merece avaliação do contexto hemorrágico.", "steps": ["Examine o umbigo e a pele adjacente com boa luz.", "Descreva cor, distribuição e evolução, perguntando sobre trauma e procedimentos.", "Correlacione com dor, sinais vitais, gestação possível e outras causas de sangramento."], "positive": "Equimose periumbilical é o achado visual; sua etiologia depende da avaliação completa.", "limit": "Não é exclusiva de pancreatite nem costuma ser um marcador precoce. A imagem é sintética, sem paciente real.", "suggestedSection": "Alterações da inspeção", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6886890/"], "file": "assets/images/A18-cullen.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "600887a00171b8171207744e7e19cabe8310aff0fce5635d8144e833685b934d", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A19", "title": "Grey Turner: equimose no flanco", "alt": "Pessoa adulta fictícia deitada de lado, com equimose irregular arroxeada e amarelada no flanco lateral; tórax e pelve permanecem cobertos.", "caption": "Equimose no flanco corresponde ao sinal de Grey Turner e pode refletir sangue que alcançou o subcutâneo a partir de planos profundos. Procure a alteração também em regiões pouco visíveis na inspeção frontal.", "steps": ["Inspecione os flancos, preservando cobertura e conforto.", "Descreva extensão, cor, lado e tempo de aparecimento; investigue trauma.", "Integre a dor, a perfusão, a hemoglobina e a possibilidade de sangramento interno."], "positive": "Equimose lateral no flanco constitui o achado, com múltiplas causas possíveis.", "limit": "Não é específica de pancreatite; sua ausência não exclui hemorragia grave ou doença retroperitoneal.", "suggestedSection": "Alterações da inspeção", "references": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6886890/"], "file": "assets/images/A19-grey-turner.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "db0fd949f8cf4f5235077d76dd274f298a7936c7c2c5ffd0dcdaf75b1296bf5e", "teachingMode": "illustration", "width": 1672, "height": 941}, {"id": "A20", "title": "Posição antálgica: inclinação anterior", "alt": "Pessoa adulta fictícia sentada na borda da maca, inclinada para a frente com antebraços apoiados em travesseiro sobre as coxas e os pés no chão, acompanhada por médica.", "caption": "A cena mostra uma pessoa sentada com inclinação anterior e apoio, uma posição que algumas pessoas adotam para aliviar dor epigástrica. É observação de comportamento antálgico, não um teste obrigatório.", "steps": ["Pergunte em que posição a dor melhora ou piora.", "Permita uma postura confortável e apoiada, sem forçar flexões.", "Registre a relação com posição e associe a história, sinais vitais, exame e investigação."], "positive": "Alívio em flexão anterior pode ocorrer na pancreatite, mas não identifica sozinho a doença.", "limit": "Esta imagem não representa a posição genupeitoral historicamente chamada de prece maometana; não exigir postura em pessoa instável.", "suggestedSection": "Pancreatite e posição antálgica", "references": ["https://www.ncbi.nlm.nih.gov/books/NBK420/"], "file": "assets/images/A20-posicao-antalgica.png", "synthetic": true, "patientDerived": false, "clinicalReview": "pending", "sha256": "592d535415362b92b7252af7f2c8e28e96cbc5e6a927aa88f8608863648bc379", "teachingMode": "illustration", "width": 1672, "height": 941}]};
